      ["pvp-disarm-battle"] = { title = "Désarmement et retour en Posture de combat", use = "Appuie une fois pour passer en Posture défensive, une deuxième fois pour lancer Désarmement et revenir aussitôt en Posture de combat. Maîtrise tactique améliorée te permet de garder jusqu'à 25 points de Rage à chaque changement.",
        requires = "Désarmement appris ; une cible qui tient une arme", mods = {  } },
      ["pvp-drop-protection"] = { title = "Retire Bénédiction de protection et attaque", use = "La Bénédiction de protection d'un Paladin allié t'empêche d'attaquer. La macro l'annule et relance ton attaque auto.",
