      ["pvp-fear-bandage"] = { title = "Cri d'intimidation, bandage sur Shift", use = "Arrête l'attaque auto et lance Cri d’intimidation sur ta cible, puis maintiens Shift pour te bander pendant qu'il fuit. Les dégâts interrompent le bandage : attention aux DoT. Mets le nom du bandage que tu as sur toi.",
