      ["pvp-free-action-potion"] = { title = "Potion de libre action, Potion de rapidité sur Shift", use = "Bois une Potion de libre action avant qu'une immobilisation ou un étourdissement tombe, ou une Potion de rapidité avec Shift pour rattraper un fuyard. Les potions partagent un temps de recharge : c'est l'une ou l'autre.",
