      ["pvp-hamstring-defensive"] = { title = "Brise-genou et retour en Posture défensive", use = "Brise-genou ne fonctionne pas en Posture défensive. Appuie une fois pour passer en Posture de combat, une deuxième fois pour lancer Brise-genou et revenir aussitôt en défensive. Shift vise ton mouseover.",
