      ["pvp-howl-or-fear"] = { title = "Hurlement perçant, Cri d'intimidation sur Shift", use = "Hébète tous les ennemis à 10 mètres ou moins avec Hurlement perçant, ou maintiens Shift pour arrêter l'attaque auto et lancer Cri d’intimidation sur ta cible, qui effraie aussi jusqu'à cinq ennemis à 8 mètres ou moins de toi.",
        requires = "Talent Hurlement perçant", mods = { "Hurlement perçant sur tous les ennemis à 10 mètres ou moins", "Arrête d'attaquer et lance Cri d’intimidation sur ta cible" } },
      ["pvp-intercept"] = { title = "Interception sur ta cible ou ton mouseover", use = "Passe en Posture berserker si besoin et lance Interception pour un étourdissement de 3 s. Maintiens Shift pour viser ton mouseover.",
        requires = "Interception appris ; Posture berserker", mods = { "Interception sur ta cible", "Interception sur la cible survolée à la place" } },
      ["pvp-intercept-bloodthirst"] = { title = "Interception, puis Sanguinaire à l'arrivée", use = "Passe en Posture berserker si besoin et lance Interception, puis appuie à nouveau une fois au contact pour Sanguinaire. Sa vitesse de course t'aide à rester collé une fois l'étourdissement terminé.",
