      ["pvp-intercept-defensive"] = { title = "Interception et retour en Posture défensive", use = "Appuie une fois pour passer en Posture berserker, une deuxième fois pour lancer Interception et revenir aussitôt en défensive. Si Interception n'est pas prêt, le deuxième appui te ramène seulement.",
