      ["pvp-intercept-hamstring"] = { title = "Interception, puis Brise-genou à l'arrivée", use = "Passe en Posture berserker si besoin et lance Interception pour l'étourdissement de 3 s. Appuie à nouveau une fois au contact pour Brise-genou avant qu'il puisse fuir.",
