      ["pvp-interrupt"] = { title = "Interruption sur un bouton", use = "Coup de bouclier avec un bouclier en Posture de combat ou défensive, Volée de coups en Posture berserker. Sans bouclier, la macro te fait d'abord passer en Posture berserker. Elle arrête aussi ton propre Heurtoir.",
