      ["pvp-last-stand-potion"] = { title = "Dernier rempart et une potion de soins", use = "Dernier rempart et une potion de soins d'un seul appui quand tu es sur le point de tomber, par exemple en portant un drapeau. Mets le nom de la potion que tu as sur toi.",
