      ["pvp-off-hand-shield"] = { title = "Main gauche vers bouclier, et retour", use = "Remplace ton arme de main gauche par un bouclier, ou l'inverse, sans toucher à ta main droite. Pratique avant un Mur protecteur ou une Maîtrise du blocage. Mets les noms de tes propres objets.",
        requires = "Ambidextrie ; un bouclier et ton arme de main gauche dans tes sacs", mods = {  } },
      ["pvp-one-key-stances"] = { title = "Les trois postures sur une touche", use = "Posture de combat sur un appui simple, défensive avec Shift et berserker avec Ctrl. Les postures ont un temps de recharge de 1 s et tu gardes jusqu'à 10 points de Rage en changeant.",
        requires = "", mods = { "Posture de combat", "Posture défensive", "Posture berserker" } },
      ["pvp-overpower-mouseover"] = { title = "Fulgurance sur ta cible ou ton mouseover", use = "Passe en Posture de combat si besoin et lance Fulgurance sur l'ennemi qui a esquivé, ou sur ton mouseover avec Shift. Avec Exaltation sanguinaire, les ennemis qui portent ton Pourfendre peuvent aussi l'ouvrir.",
        requires = "Posture de combat ; l'ennemi a esquivé, ou Exaltation sanguinaire s'est déclenchée", mods = { "Fulgurance sur ta cible", "Fulgurance sur la cible survolée à la place" } },
      ["pvp-shield-bash-swap"] = { title = "Coup de bouclier en équipant le bouclier", use = "Équipe ton arme à une main et ton bouclier et lance Coup de bouclier depuis Posture de combat : pas besoin de passer en berserker pour Volée de coups. Si seul le changement se fait, appuie à nouveau pour frapper.",
        requires = "Coup de bouclier appris ; une arme à une main et un bouclier dans tes sacs. Mets leurs noms à la place de One-Hand Name et Shield Name", mods = {  } },
      ["pvp-shield-slam-purge"] = { title = "Heurt de bouclier pour retirer un buff de ta cible ou ton mouseover", use = "Heurt de bouclier sur ta cible, ou sur ton mouseover avec Shift. Il a 50 % de chances de retirer un effet magique : ça vaut le coup sur un Prêtre sous bouclier ou un Paladin sous Bénédiction de liberté.",
