      ["pvp-shield-wall-swap"] = { title = "Mur protecteur en équipant le bouclier", use = "Équipe ton arme à une main et ton bouclier si tu n'as pas de bouclier, passe en Posture défensive et utilise Mur protecteur. Mets les noms de tes propres objets.",
