      ["pvp-spearing-strike"] = { title = "Frappe transperçante sur un cavalier", use = "Frappe transperçante sur ta cible, ou sur ton mouseover avec Shift, pour faire tomber un ennemi de sa monture.",
        requires = "Talent Frappe transperçante ; Posture de combat. La mise à jour du 1 octobre a supprimé l'obligation d'avoir une arme à deux mains", mods = { "Frappe transperçante sur ta cible", "Frappe transperçante sur la cible survolée à la place" } },
      ["pvp-sweeping-mortal-strike"] = { title = "Attaques circulaires et Frappe mortelle ensemble", use = "Utilise-la quand deux ennemis sont côte à côte, comme un soigneur à côté de ta cible. Attaques circulaires ne déclenche pas le temps de recharge global : les deux partent d'un seul appui si tu as 60 points de Rage.",
        requires = "Talents Attaques circulaires et Frappe mortelle ; Posture de combat", mods = {  } },
      ["pvp-target-swap"] = { title = "Ennemi le plus proche, ou retour au dernier", use = "Cible l'ennemi le plus proche si tu n'en as pas de vivant et attaque. Maintiens Shift pour revenir plutôt à ton ennemi précédent.",
