      ["pvp-vanguard-concussion"] = { title = "Charge depuis la Posture défensive, puis Bourrasque", use = "Avec Avant-garde, tu peux lancer Charge hors combat sans quitter la Posture défensive. Appuie à nouveau à l'arrivée pour lui lancer Bourrasque pendant 5 s.",
