      ["class-wide-resistance-auras"] = { title = "Auras de résistance sur un bouton", use = "Aura de résistance au Feu sur un appui normal. Maintiens Shift pour Givre ou Ctrl pour Ombre quand le combat l'exige. Dans Forever, elles touchent tout le raid dans un rayon de 30 mètres.",
        requires = "Les trois auras de résistance apprises (celle de Feu au niveau 36)", mods = { "Aura de résistance au Feu", "Aura de résistance au Givre", "Aura de résistance à l'Ombre" } },
      ["class-wide-undead"] = { title = "Exorcisme ou Renvoi des morts-vivants", use = "Exorcisme sur une cible Mort-vivant ou Démon. Maintiens Shift pour Renvoi des morts-vivants et faire fuir un ennemi mort-vivant.",
        requires = "Tu connais Exorcisme (niveau 20) et Renvoi des morts-vivants (niveau 24)", mods = { "Exorcisme sur ta cible", "Renvoi des morts-vivants sur ta cible" } },
      ["holy-cleanse"] = { title = "Epuration en mouseover", use = "Epuration retire un poison, une maladie et un effet magique de la cible survolée, puis de ta cible amicale, puis de toi. Maintiens Alt pour t'épurer toi-même.",
        requires = "Epuration appris (niveau 42)", mods = { "Epuration en mouseover, puis sur ta cible amicale, puis sur toi", "Epuration sur toi" } },
      ["holy-divine-favor"] = { title = "Faveur divine avant un soin", use = "Active Faveur divine et soigne en un seul appui pour un soin critique assuré. Lumière sacrée par défaut, Éclair lumineux avec Shift.",
        requires = "Talent Faveur divine ; temps de recharge de 2 minutes", mods = { "Faveur divine, puis Lumière sacrée", "Faveur divine, puis Éclair lumineux" } },
      ["holy-flash-of-light"] = { title = "Éclair lumineux en mouseover", use = "Garde ta cible ennemie tout en soignant le cadre de groupe sous ton curseur.",
        requires = "Éclair lumineux appris", mods = {  } },
      ["holy-flash-of-light-ranks"] = { title = "Rangs d'Éclair lumineux sur Shift et Ctrl", use = "Remonte la vie de la cible survolée ou de ta cible amicale avec ton rang maximum, ou un rang moins cher avec Shift (rang 5) ou Ctrl (rang 3).",
        requires = "Tu connais Éclair lumineux rangs 3 et 5 (niveau 50) ; remplace-les par les rangs que tu as", mods = { "Ton rang le plus élevé de Éclair lumineux", "Éclair lumineux rang 5", "Éclair lumineux rang 3" } },
      ["holy-holy-light"] = { title = "Lumière sacrée en mouseover", use = "Soigne d'abord l'allié survolé, puis ta cible, puis toi-même.",
        requires = "", mods = {  } },
      ["holy-holy-light-ranks"] = { title = "Rangs de Lumière sacrée sur Shift et Ctrl", use = "Soigne la cible survolée ou ta cible amicale avec ton rang maximum, ou un rang moins cher avec Shift (rang 7) ou Ctrl (rang 5).",
        requires = "Tu connais Lumière sacrée rangs 5 et 7 (niveau 46) ; remplace-les par les rangs que tu as", mods = { "Ton rang le plus élevé de Lumière sacrée", "Lumière sacrée rang 7", "Lumière sacrée rang 5" } },
      ["holy-holy-shock"] = { title = "Horion sacré sur un allié ou un ennemi", use = "Horion sacré sur la cible survolée, puis ta cible, puis toi. Ça soigne un allié et blesse un ennemi. Maintiens Alt pour te lancer le Horion.",
        requires = "Talent Horion sacré (il commence au niveau 30 dans Forever)", mods = { "Horion sacré en mouseover, puis sur la cible, puis sur toi", "Horion sacré sur toi" } },
      ["holy-lights-vigil"] = { title = "Vigile de Lumière, puis Horion sacré", use = "Marque l’allié survolé ou ta cible avec Vigile de Lumière, puis maintiens Shift et appuie pour lancer Horion sacré sur la même cible et obtenir l’effet bonus.",
        requires = "Talents Vigile de Lumière et Horion sacré ; la marque dure 30 secondes, et depuis le 2 novembre, elle ne se pose que sur les alliés", mods = { "Vigile de Lumière sur l’allié survolé, ta cible amicale ou toi", "Horion sacré sur la cible survolée ou ta cible" } },
      ["holy-purify"] = { title = "Purification en mouseover", use = "Retire une maladie et un poison de la cible survolée, puis de ta cible amicale, puis de toi-même.",
        requires = "Purification appris (niveau 8)", mods = {  } },
      ["holy-seal-wisdom"] = { title = "Sceau de sagesse, Sceau de lumière ou Jugement", use = "Maintiens Shift pour Sceau de sagesse ou Ctrl pour Sceau de lumière, puis appuie normalement pour juger. Jugement ne consomme plus le Sceau, donc tu n'as pas à le relancer.",
        requires = "Sceau de sagesse (niveau 38) ou Sceau de lumière (niveau 30) ; le Sceau et Jugement demandent chacun un appui", mods = { "Jugement sur ta cible", "Sceau de sagesse", "Sceau de lumière" } },
      ["holy-tank-heal"] = { title = "Soigner la personne que l'ennemi attaque", use = "Avec un ennemi en cible, Éclair lumineux va sur la cible survolée, puis ta cible amicale, puis la personne que cet ennemi attaque. Maintiens Shift pour Lumière sacrée.",
        requires = "Éclair lumineux appris", mods = { "Éclair lumineux en mouseover, sur ta cible amicale ou sur la cible de ton ennemi", "Lumière sacrée sur les mêmes cibles" } },
      ["protection-bulwark-protection"] = { title = "Rempart de templier ou Protection divine", use = "Rempart de templier te pose un bouclier qui absorbe l'équivalent de ta vie max pendant 8 secondes. Maintiens Shift pour Protection divine à la place. Les deux appliquent Longanimité.",
        requires = "Talent Rempart de templier ; aucun des deux ne marche tant que Longanimité est active", mods = { "Rempart de templier", "Protection divine" } },
      ["protection-consecration"] = { title = "Consécration et Fureur vertueuse", use = "Maintiens Shift pour activer Fureur vertueuse avant un pull. Appuie normalement pour Consécration.",
        requires = "Consécration et Fureur vertueuse appris", mods = { "Consécration", "Fureur vertueuse" } },
      ["protection-holy-shield-judgement"] = { title = "Bouclier sacré et Jugement", use = "Un appui juge (Jugement ne déclenche pas le temps de recharge global) et lève Bouclier sacré.",
        requires = "Talent Bouclier sacré ; un bouclier équipé ; un Sceau actif", mods = {  } },
      ["protection-judge-mouseover"] = { title = "Juger le mob sous ton curseur", use = "Juge l'ennemi survolé, ou ta cible si tu n'en survoles aucun. Avec Sceau de fureur actif, ce Jugement provoque pendant 3 secondes.",
        requires = "Sceau de fureur actif ; Jugement porte à 10 mètres", mods = {  } },
      ["protection-righteous-fury"] = { title = "Fureur vertueuse active, Shift pour l'annuler", use = "Appuie pour activer Fureur vertueuse avant un pull. Maintiens Shift pour l'annuler quand tu passes aux dégâts ou aux soins.",
        requires = "Fureur vertueuse appris (niveau 10)", mods = { "Fureur vertueuse", "Annuler Fureur vertueuse" } },
      ["protection-righteous-strikes"] = { title = "Marteau du vertueux ou Frappe sacrée", use = "Marteau du vertueux frappe ta cible et jusqu'à 3 ennemis proches, avec un temps de recharge de 6 secondes. Maintiens Shift pour Frappe sacrée.",
        requires = "Marteau du vertueux (niveau 40) et Frappe sacrée appris", mods = { "Marteau du vertueux", "Frappe sacrée" } },
      ["protection-sacrifice"] = { title = "Bénédiction de sacrifice sur un membre du groupe", use = "Mets Bénédiction de sacrifice sur la cible survolée ou ta cible amicale pour qu'une partie de chaque coup te revienne. Ça ne marche que sur les membres du groupe.",
        requires = "Bénédiction de sacrifice appris (niveau 46)", mods = {  } },
      ["protection-seal-of-fury"] = { title = "Sceau de fureur ou Jugement", use = "Maintiens Shift pour appliquer Sceau de fureur. Un appui normal juge, et avec le Sceau actif, ce Jugement provoque ta cible pendant 3 secondes.",
        requires = "Tu connais Sceau de fureur (niveau 10) ; le Sceau et Jugement demandent chacun un appui", mods = { "Jugement sur ta cible", "Sceau de fureur" } },
      ["protection-seal-pick"] = { title = "Sceau de fureur, de piété ou de justice", use = "Sceau de fureur par défaut. Shift prend Sceau de piété, et Ctrl prend Sceau de justice, dont le Jugement empêche l'ennemi de fuir.",
        requires = "Tu connais Sceau de fureur (niveau 10) et Sceau de justice (niveau 22)", mods = { "Sceau de fureur", "Sceau de piété", "Sceau de justice" } },
      ["protection-swift-judgement"] = { title = "Jugement ou Jugement rapide", use = "Appuie pour juger. Maintiens Shift pour Jugement rapide, qui libère de nouveau ton Sceau avec son propre temps de recharge de 1 minute, distinct de celui de Jugement.",
        requires = "Talent Jugement rapide, qui nécessite désormais Rempart de templier ; un Sceau actif", mods = { "Jugement sur ta cible", "Jugement rapide" } },
      ["pvp-assist-attack"] = { title = "Assister un allié et attaquer", use = "Prend la cible de ta cible amicale et commence à l'attaquer. Maintiens Shift pour assister plutôt l'allié sous ton curseur.",
        requires = "", mods = { "Assister ta cible amicale", "Assister l'allié survolé" } },
      ["pvp-bubble-heal"] = { title = "Bouclier divin, puis soin ou bandage sur toi", use = "Le premier appui te met en bulle. Appuie à nouveau pour te soigner dedans : Lumière sacrée par défaut, Éclair lumineux avec Shift, ou un bandage avec Ctrl.",
        requires = "Tu connais Bouclier divin (niveau 34) ; remplace Bandage épais en étoffe runique par le bandage que tu as sur toi", mods = { "Bouclier divin, puis Lumière sacrée sur toi", "Bouclier divin, puis Éclair lumineux sur toi", "Bouclier divin, puis ton bandage sur toi" } },
      ["pvp-bubble-hearth"] = { title = "Bouclier divin, puis ta Pierre de foyer", use = "La vieille technique de fuite. Le premier appui te met en bulle, le second lance ta Pierre de foyer. À partir du niveau 50, la bulle dure 12 secondes, assez pour couvrir les 10 secondes de la pierre si tu rappuies tout de suite.",
        requires = "Tu connais Bouclier divin (niveau 34 ; rang 2 au niveau 50) ; Pierre de foyer disponible", mods = {  } },
      ["pvp-bulwark-freedom"] = { title = "Rempart de templier et Liberté sur toi", use = "Une absorption et un anti-ralentissement en un seul appui, pour porter un drapeau ou quitter un combat. Bulwark ne déclenche pas le temps de recharge global, donc Liberté suit tout de suite, même si Bulwark n'est pas prêt.",
        requires = "Talent Rempart de templier (applique Longanimité) ; tu connais Bénédiction de liberté (niveau 18). Faveur du Gardien prolonge Liberté jusqu'à 16 secondes.", mods = {  } },
      ["pvp-bulwark-heal"] = { title = "Rempart de templier, puis te soigner", use = "L'absorption encaisse les dégâts pendant que tu incantes. Éclair lumineux sur toi par défaut, Lumière sacrée avec Shift, ou Imposition des mains avec Ctrl quand le soin doit arriver tout de suite.",
        requires = "Talent Rempart de templier (applique Longanimité) ; Imposition des mains vide ton mana", mods = { "Rempart, puis Éclair lumineux sur toi", "Rempart, puis Lumière sacrée sur toi", "Rempart, puis Imposition des mains sur toi" } },
      ["pvp-bulwark-stun"] = { title = "Rempart de templier, puis Marteau de la justice", use = "Active l'absorption et étourdit ta cible d'un seul appui, car Bulwark ne déclenche pas le temps de recharge global. Maintiens Shift pour étourdir plutôt la cible survolée.",
        requires = "Talent Rempart de templier (applique Longanimité) ; tu connais Marteau de la justice. Marteau de la justice amélioré ramène l'étourdissement plus tôt.", mods = { "Rempart, puis Marteau de la justice sur ta cible", "Rempart, puis Marteau de la justice sur la cible survolée" } },
      ["pvp-dismount-command"] = { title = "Descendre de monture, Sceau d'autorité et attaquer", use = "Pour quand on te tombe dessus sur la route : un appui te fait descendre de monture, active Sceau d'autorité et lance tes attaques sur ta cible.",
        requires = "Talent Sceau d'autorité", mods = {  } },
      ["pvp-execute-burst"] = { title = "Bijoux, Jugement et Marteau de courroux", use = "Jugement ne déclenche pas le temps de recharge global, donc un appui juge et lance Marteau de courroux sur une cible à 20 % de vie ou moins. Maintiens Shift pour utiliser d'abord tes deux bijoux.",
        requires = "Marteau de courroux (niveau 44), que cinq rangs de Champion de la lumière rendent instantané ; un Sceau actif pour Jugement ; des bijoux activables pour Shift", mods = { "Jugement, puis Marteau de courroux sur ta cible", "Les deux bijoux, puis la même chose" } },
      ["pvp-favor-shock"] = { title = "Faveur divine avant Horion sacré", use = "Active Faveur divine et Horion sacré en un seul appui pour un Horion critique assuré. Ça soigne la cible survolée, ta cible ou toi, et Shift l'envoie sur un ennemi.",
        requires = "Talents Faveur divine et Horion sacré (Horion sacré commence au niveau 30 dans Forever)", mods = { "Soigne la cible survolée, ta cible ou toi-même", "Inflige des dégâts à l'ennemi survolé ou à ta cible" } },
      ["pvp-freedom"] = { title = "Bénédiction de liberté sur un allié ou sur toi", use = "Libère la cible survolée, puis ta cible amicale, puis toi-même. Maintiens Alt pour te libérer toi. Elle donne 10 secondes d'immunité aux effets qui gênent le déplacement.",
        requires = "Bénédiction de liberté appris (niveau 18)", mods = { "Liberté sur la cible survolée, puis ta cible amicale, puis toi", "Liberté sur toi" } },
      ["pvp-hammer-of-wrath-finish"] = { title = "Marteau de courroux sur la cible ou en mouseover", use = "Achève à distance un ennemi à 20 % de vie ou moins. Maintiens Shift pour choisir celui sous ton curseur.",
        requires = "Tu connais Marteau de courroux (niveau 44) ; la cible doit être à 20 % de vie ou moins", mods = { "Marteau de courroux sur ta cible", "Marteau de courroux sur la cible survolée" } },
      ["pvp-hoj-judgement"] = { title = "Étourdir, puis juger la cible étourdie", use = "Marteau de la justice sur un appui normal, puis maintiens Shift pour juger pendant que la cible est étourdie. Le Jugement du Sceau d'autorité frappe environ deux fois plus fort sur une cible étourdie ou neutralisée.",
        requires = "Sceau d'autorité actif (talent Vindicte) ; tu connais Marteau de la justice", mods = { "Marteau de la justice sur ta cible", "Jugement sur ta cible" } },
      ["pvp-hoj-stun"] = { title = "Marteau de la justice sur la cible ou en mouseover", use = "Abandonne ton incantation, te fait descendre de ta monture, puis étourdit ta cible. Maintiens Shift pour étourdir plutôt l'ennemi sous ton curseur.",
        requires = "Tu connais Marteau de la justice (niveau 8) ; ça annule une incantation même si l'étourdissement est en recharge", mods = { "Étourdis ta cible", "Étourdis plutôt la cible survolée" } },
      ["pvp-iron-creed-strike"] = { title = "Frappe sacrée avec Fureur vertueuse sur Shift", use = "Frappe sacrée et continue de frapper. Avec Credo de fer, Frappe sacrée réduit les dégâts que tu subis jusqu'à 6 % pendant 6 secondes tant que Fureur vertueuse est active, alors laisse-la active en PvP. Shift l'active.",
        requires = "Talent Credo de fer ; tu connais Frappe sacrée, et Fureur vertueuse (niveau 10)", mods = { "Frappe sacrée sur ta cible", "Fureur vertueuse" } },
      ["pvp-judge-and-shock"] = { title = "Jugement et Horion sacré sur ton ennemi", use = "Jugement ne déclenche pas le temps de recharge global, donc un appui juge ta cible ennemie et lui lance Horion sacré. Maintiens Shift pour utiliser aussi ton premier bijou et Faveur divine, ce qui rend le Horion critique à coup sûr.",
        requires = "Talent Horion sacré ; un Sceau actif, et Jugement ne porte qu'à 10 mètres ; Faveur divine et un bijou activable dans ton premier emplacement pour Shift", mods = { "Jugement, puis Horion sacré sur ta cible ennemie", "Faveur divine et ton premier bijou, puis pareil" } },
      ["pvp-lay-on-hands-pvp"] = { title = "Imposition des mains : toi, ou un allié avec Shift ou Ctrl", use = "Annule ton incantation (même si Imposition des mains est en recharge), puis te lance Imposition des mains. Shift choisit l'allié survolé et Ctrl ta cible amicale.",
        requires = "Imposition des mains appris (niveau 10)", mods = { "Imposition des mains sur toi", "Imposition des mains sur l'allié survolé", "Imposition des mains sur ta cible amicale" } },
      ["pvp-party-cleanse"] = { title = "Epuration sur le membre 1 ou 2 du groupe", use = "Epuration sur un membre du groupe sans survoler son cadre. Shift choisit le membre 1 du groupe et Ctrl le membre 2. Sans modificateur, ça va sur la cible survolée, puis ta cible amicale, puis toi.",
        requires = "Tu connais Epuration (niveau 42) ; les membres 1 et 2 du groupe suivent l'ordre de tes cadres de groupe", mods = { "Epuration en mouseover, puis sur ta cible amicale, puis sur toi", "Epuration sur le membre 1 du groupe", "Epuration sur le membre 2 du groupe" } },
      ["pvp-party-sacrifice"] = { title = "Bénédiction de sacrifice sur le membre 1 ou 2 du groupe", use = "Sacrifice ne va que sur les membres du groupe, donc Shift le met sur le membre 1 et Ctrl sur le membre 2. Sans modificateur, il va sur la cible survolée ou ta cible amicale. Une partie de chaque coup qu'elle subit t'est transférée.",
        requires = "Tu connais Bénédiction de sacrifice (niveau 46) ; les membres 1 et 2 du groupe suivent l'ordre de tes cadres de groupe", mods = { "Sacrifice sur l'allié survolé, puis ta cible amicale", "Sacrifice sur le membre du groupe 1", "Sacrifice sur le membre du groupe 2" } },
      ["pvp-party-shock"] = { title = "Horion sacré sur le membre 1 ou 2 du groupe", use = "Lance Horion sacré sur un membre du groupe sans survoler son cadre. Shift choisit le membre 1 et Ctrl le membre 2. Sans modificateur, il va sur la cible survolée, puis ta cible amicale, puis toi.",
        requires = "Talent Horion sacré ; les membres 1 et 2 du groupe suivent l'ordre de tes cadres de groupe", mods = { "Horion sacré en mouseover, puis sur ta cible amicale, puis sur toi", "Horion sacré sur le membre du groupe 1", "Horion sacré sur le membre du groupe 2" } },
      ["pvp-racial-escape"] = { title = "Évasion raciale pour Humain, Nain ou Mort-vivant", use = "Un seul bouton pour ton trait racial, quel qu'il soit. Volonté de survie retire les étourdissements, Forme de pierre les saignements, poisons et maladies, et Volonté des Réprouvés le charme, la peur et le sommeil.",
        requires = "Humain, Nain ou Mort-vivant ; les lignes des autres races ne font rien", mods = {  } },
      ["pvp-reckoning-charges"] = { title = "Stocker les charges de Rétribution, puis les libérer", use = "Maintiens Shift pour arrêter l'attaque automatique et lever Bouclier sacré, pour que les charges de Rétribution de tes blocages s'accumulent au lieu de partir une par une. Appuie sans modificateur pour frapper et les dépenser.",
        requires = "Talents Rétribution et Bouclier sacré ; un bouclier équipé ; jusqu'à 4 charges. Dans Classic, changer de cible avec l'attaque automatique active les faisait perdre.", mods = { "Attaque ta cible pour consommer les charges", "Arrêter d'attaquer et lever Bouclier sacré" } },
      ["pvp-repentance"] = { title = "Repentir sur ta cible, en mouseover ou sur sa cible", use = "Neutralise un Humanoïde pendant 6 secondes au maximum. Shift choisit la cible survolée, et Alt la cible de ta cible si c'est un ennemi.",
        requires = "Talent Repentir ; Humanoïdes uniquement, et les dégâts le brisent", mods = { "Repentir sur ta cible", "Repentir sur la cible survolée", "Repentir sur la cible de ta cible" } },
      ["pvp-repentance-heal"] = { title = "Repentir sans le briser, puis soigner", use = "Arrête ton attaque automatique pour que ton prochain coup ne réveille pas la cible, puis lance Repentir sur elle. Maintiens Shift pour Éclair lumineux ou Ctrl pour Lumière sacrée sur toi pendant qu'elle est neutralisée.",
        requires = "Talent Repentir ; Humanoïdes uniquement, et le moindre dégât le brise, Consécration comprise", mods = { "Arrêter d'attaquer, puis Repentir sur ta cible", "Éclair lumineux sur toi", "Lumière sacrée sur toi" } },
      ["pvp-repentance-judgement"] = { title = "Repentir, puis juger pour des dégâts doublés", use = "Repentir sans modificateur, Jugement avec Shift. Le Jugement du Sceau d'autorité frappe environ deux fois plus fort sur une cible neutralisée, comme sur une cible étourdie, et le coup brise Repentir.",
        requires = "Talents Repentir et Sceau d'autorité ; Sceau d'autorité actif", mods = { "Repentir sur ta cible", "Jugement sur ta cible" } },
      ["pvp-seal-pick-pvp"] = { title = "Sceau d'autorité, de justice, de lumière ou de sagesse", use = "Sceau d'autorité par défaut. Shift prend Justice, qui peut étourdir à l'impact. Ctrl prend Lumière et Alt Sagesse.",
        requires = "Talent Sceau d'autorité ; Sceau de sagesse est au niveau 38", mods = { "Sceau d'autorité", "Sceau de justice", "Sceau de lumière", "Sceau de sagesse" } },
      ["pvp-shock-their-target"] = { title = "Horion sacré sur la personne que ton ennemi frappe", use = "Garde l'ennemi en cible et soigne l'allié qu'il attaque, l'allié survolé en priorité. S'il te frappe, la macro te soigne. Maintiens Shift pour lancer plutôt Horion sacré sur l'ennemi.",
        requires = "Talent Horion sacré (il commence au niveau 30 dans Forever)", mods = { "Soigne la cible survolée, ta cible amicale ou la cible de ton ennemi, puis toi", "Horion sacré sur ta cible ennemie" } },
      ["pvp-shock-then-holy-light"] = { title = "Horion sacré, puis une Lumière sacrée plus rapide", use = "Le premier appui lance Horion sacré sur l'allié survolé, ta cible amicale ou toi, et l'appui suivant lance Lumière sacrée de la même façon. Si le Horion fait un critique, Imprégnation de lumière retire jusqu'à une seconde à son incantation.",
        requires = "Talents Horion sacré et Imprégnation de lumière ; tant que Horion sacré est en recharge, la séquence attend à cette étape", mods = { "Horion sacré, puis Lumière sacrée à l'appui suivant", "Faveur divine d'abord, pour que le prochain soin soit un critique assuré" } },
      ["pvp-shock-yourself"] = { title = "Arrêter l'incantation et te lancer Horion sacré", use = "Annule le soin en cours et te lance Horion sacré aussitôt, pour quand on te saute dessus en pleine incantation. Maintiens Shift pour le lancer sur l'allié survolé. L'incantation est annulée même si Horion sacré est en recharge.",
        requires = "Talent Horion sacré (il commence au niveau 30 dans Forever) ; temps de recharge de 10 secondes", mods = { "Arrêter l'incantation, puis Horion sacré sur toi", "Arrêter l'incantation, puis Horion sacré sur l'allié survolé" } },
      ["pvp-stun-into-repentance"] = { title = "Marteau de la justice, puis Repentir", use = "Enchaîne ton étourdissement et Repentir sur une même cible. Le premier appui arrête ton attaque et l'étourdit ; appuie à nouveau juste avant la fin de l'étourdissement pour Repentir. Profites-en pour te soigner ou te replacer.",
        requires = "Talent Repentir ; tu connais Marteau de la justice ; tant que Marteau de la justice est en recharge, la séquence attend à cette étape", mods = {  } },
      ["pvp-stun-then-justice"] = { title = "Marteau de la justice, puis Sceau de justice", use = "Le premier appui étourdit ta cible et lance tes attaques. Appuie à nouveau pour Sceau de justice, pour que chaque coup ait une chance de l'étourdir 2 secondes de plus quand le Marteau se dissipe.",
        requires = "Tu connais Marteau de la justice et Sceau de justice (niveau 22) ; tant que Marteau de la justice est en recharge, la séquence attend à cette étape", mods = {  } },
      ["pvp-target-nearest"] = { title = "Cibler l'ennemi le plus proche et attaquer", use = "Prend l'ennemi le plus proche si tu n'as pas d'ennemi vivant en cible, puis lance l'attaque automatique. Shift passe toujours à l'ennemi le plus proche, et Alt revient à ta dernière cible ennemie.",
        requires = "", mods = { "Ennemi le plus proche si tu n'en as pas, puis attaquer", "Toujours l'ennemi le plus proche", "Ta dernière cible ennemie" } },
      ["pvp-trinket-freedom"] = { title = "Bijou, puis Liberté sur toi", use = "Utilise le bijou de ton premier emplacement, puis Bénédiction de liberté sur toi. Maintiens Shift pour sauter le bijou.",
