        requires = "Brûlure de mana appris", mods = {  } },
      ["discipline-penance"] = { title = "Pénitence pour soigner, Shift pour les dégâts", use = "Soigne l'allié survolé, ta cible ou toi ; maintiens Shift pour infliger des dégâts à ta cible hostile. Rappuyer laisse finir ta canalisation de Pénitence en cours.",
        requires = "Talent Pénitence (Discipline). Le rang 1 est au niveau 30, avec 12 s de recharge.", mods = { "Soigne la cible survolée, puis ta cible, puis toi-même", "Inflige des dégâts à ta cible hostile" } },
      ["discipline-power-infusion"] = { title = "Infusion de puissance sur un allié ou sur toi", use = "Mets Infusion de puissance sur l'allié sous ton curseur, puis ta cible, puis toi. Alt te choisit toujours.",
        requires = "Talent Infusion de puissance (Discipline, niveau 40)", mods = { "Infusion sur la cible survolée, puis ta cible, puis toi", "Infusion sur toi" } },
      ["discipline-prayer-of-fortitude"] = { title = "Prière de robustesse en mouseover", use = "Lance Prière de robustesse sur l'allié sous ton curseur, ta cible ou toi.",
        requires = "Tu connais Prière de robustesse (niveau 48). L'infobulle de Forever couvre tous les membres du groupe et du raid, alors que celle de Classic couvrait le groupe de la cible.", mods = {  } },
      ["discipline-shield"] = { title = "Mot de pouvoir : Bouclier en mouseover", use = "Pose un bouclier sur l'allié survolé, ta cible ou toi-même.",
        requires = "Mot de pouvoir : Bouclier appris", mods = {  } },
      ["discipline-shield-downrank"] = { title = "Mot de pouvoir : Bouclier, rang 6 avec Shift", use = "Pose un bouclier sur la cible survolée, ta cible ou toi-même. Maintiens Shift pour le rang 6 quand un bouclier plus léger et moins cher suffit.",
        requires = "Tu connais Mot de pouvoir : Bouclier rang 6 (niveau 36)", mods = { "Bouclier de rang maximum sur la cible survolée, ta cible ou toi", "Bouclier de rang 6 sur la même cible" } },
      ["discipline-shield-modifiers"] = { title = "Mot de pouvoir : Bouclier avec Shift et Alt", use = "Pose un bouclier sur la cible survolée, ta cible ou toi-même. Shift protège la cible de ta cible, Alt te protège.",
        requires = "Mot de pouvoir : Bouclier appris", mods = { "Bouclier sur la cible survolée, puis ta cible, puis toi", "Bouclier sur la cible de ta cible si c'est un allié", "Bouclier sur toi" } },
      ["holy-disease-cleanse"] = { title = "Abolir maladie, Guérison des maladies avec Shift", use = "Abolir maladie sur la cible survolée, ta cible ou toi. Maintiens Shift pour Guérison des maladies sur une seule cible.",
        requires = "Tu connais Abolir maladie (niveau 32). Avant ça, utilise une macro qui ne lance que Guérison des maladies.", mods = { "Abolir maladie sur la cible survolée, ta cible ou toi", "Guérison des maladies sur la même cible" } },
      ["holy-flash-heal"] = { title = "Soins rapides en mouseover", use = "Soigne le cadre de groupe sous ton curseur, puis ta cible, puis toi-même.",
        requires = "Soins rapides appris", mods = {  } },
      ["holy-greater-heal"] = { title = "Soins supérieurs, rang 1 avec Shift", use = "Soins supérieurs sur la cible survolée, ta cible ou toi. Maintiens Shift pour le rang 1 quand les dégâts sont faibles.",
        requires = "Soins supérieurs appris (niveau 40)", mods = { "Soins supérieurs au rang max sur la cible survolée, ta cible ou toi", "Soins supérieurs rang 1 sur la même cible" } },
      ["holy-holy-fire"] = { title = "Flammes sacrées ou Châtiment", use = "Maintiens Shift pour Châtiment ; appuie normalement pour Flammes sacrées.",
        requires = "Flammes sacrées appris", mods = { "Lancer Flammes sacrées", "Lancer Châtiment" } },
      ["holy-litany-alternate"] = { title = "Alterner deux soins pour Litanie de Lumière", use = "Alterne Soins rapides et Soins supérieurs sur un bouton pour que chaque sort diffère du précédent, ce que Litanie de Lumière récompense.",
        requires = "Talent Litanie de Lumière (Sacré) et tu connais Soins supérieurs (niveau 40). La séquence repart de zéro après 4 secondes sans appui.", mods = {  } },
      ["holy-prayer-of-healing"] = { title = "Prière de soins sur le groupe de ton choix", use = "Lance Prière de soins sur l'allié sous ton curseur pour soigner son groupe, familiers compris : c'est toi qui choisis le groupe soigné.",
        requires = "Tu connais Prière de soins (niveau 30). Blizzard confirme que ça soigne le groupe de la cible, familiers compris ; le client indique un rayon de 40 mètres. Dans Classic, ça soignait ton propre groupe.", mods = {  } },
      ["holy-prayer-of-mending"] = { title = "Prière de guérison en mouseover", use = "Mets Prière de guérison sur la cible survolée, ta cible ou toi. Les dégâts ou les soins non périodiques déclenchent son soin et un saut vers un membre du groupe ou du raid proche.",
        requires = "Talent Prière de guérison (Sacré) ; le rang 1 est au niveau 40 dans le client, avec 10 s de recharge. Blizzard parle de cinq soins et d'une seule application active par cible ; l'infobulle parle de cinq sauts et d'une cible par lanceur. On n'a pas testé ces limites en jeu.", mods = {  } },
      ["holy-pull-wand"] = { title = "Pull aux Flammes sacrées, puis baguette", use = "Ouvre avec Flammes sacrées au premier appui, puis appuie à nouveau pour lancer la baguette.",
        requires = "Tu connais Flammes sacrées ; une baguette équipée", mods = {  } },
      ["holy-renew"] = { title = "Rénovation en mouseover, rang 5 avec Shift", use = "Rénovation sur la cible survolée, ta cible ou toi. Maintiens Shift pour le rang 5 et économiser du mana. Blizzard confirme que plusieurs Prêtres peuvent garder chacun leur Rénovation sur la même cible.",
        requires = "Tu connais Rénovation. Le rang 5 arrive au niveau 32.", mods = { "Rénovation au rang max sur la cible survolée, ta cible ou toi", "Rénovation rang 5 sur la même cible" } },
      ["holy-smite-target-of-target"] = { title = "Châtiment sur la cible de ton tank", use = "Châtiment sur ta cible hostile, ou sur l'ennemi que ta cible amicale attaque. Garde ton tank en cible pour faire des dégâts entre deux soins ; ça n'interrompt pas une canalisation.",
        requires = "", mods = {  } },
      ["pvp-assist-flay"] = { title = "Fouet mental sur la cible de ton allié", use = "Fouet mental sur ta cible hostile. Avec un allié en cible, ça fouette et ralentit la cible de cet allié, comme l'ennemi que ton Guerrier poursuit, sans quitter ton allié.",
        requires = "Talent Fouet mental (Ombre, niveau 20)", mods = {  } },
      ["pvp-chastise"] = { title = "Châtiment sur la cible ou en mouseover", use = "Châtiment sur ta cible pour l'immobiliser pendant 2 secondes. Maintiens Shift pour la cible survolée.",
        requires = "Prêtre nain. Châtiment est un sort racial des Nains dans Forever (2 min de recharge, 20 mètres). Ça ne marche que sur les Humanoïdes.", mods = { "Châtiment sur ta cible", "Châtiment sur la cible survolée" } },
      ["pvp-confounding-flash"] = { title = "Arrêter et Éclair déconcertant", use = "Annule ton incantation et désoriente tous les ennemis à 8 mètres ou moins pendant 3 secondes. Le moindre dégât rompt l'effet.",
        requires = "Prêtre gnome. Éclair déconcertant est un sort racial des Gnomes (niveau 10, 0.5 s d'incantation, 2 min de recharge).", mods = {  } },
      ["pvp-control"] = { title = "Contrôle mental, Shift pour Entraves des morts-vivants", use = "Contrôle mental sur l'ennemi sous ton curseur, ou sur ta cible. Maintiens Shift pour Entraves des morts-vivants à la place.",
        requires = "Tu connais Contrôle mental (niveau 30). Le rang 3 marche sur les humanoïdes jusqu'au niveau 62. Tu connais Entraves des morts-vivants pour Shift.", mods = { "Contrôle mental sur la cible survolée, puis ta cible", "Entraves des morts-vivants sur la cible survolée, puis ta cible" } },
      ["pvp-desperate-prayer"] = { title = "Prière du désespoir, Shift pour un bouclier", use = "Annule ton incantation et utilise Prière du désespoir. Maintiens Shift pour te mettre plutôt un bouclier.",
        requires = "Prêtre nain. Prière du désespoir est un sort racial des Nains dans Forever (10 min de recharge). Les Humains ont Grâce divine à la place.", mods = { "Arrêter l'incantation, Prière du désespoir", "Arrête ton incantation, bouclier sur toi" } },
      ["pvp-dispel-keys"] = { title = "Dissipation de la magie sur quatre cibles", use = "Un seul bouton Dissipation de la magie : ta cible par défaut, la cible survolée avec Shift, toi avec Ctrl, la cible de ta cible avec Alt.",
        requires = "Dissipation de la magie appris", mods = { "Dissipation sur ta cible", "Dissipation sur la cible survolée", "Dissipation sur toi", "Dissipation sur la cible de ta cible si c'est un allié" } },
      ["pvp-dot-button"] = { title = "Mot de l'ombre : Douleur, Shift pour Peste dévorante", use = "Mot de l’ombre : Douleur sur la cible survolée ou ta cible. Maintiens Shift pour Peste dévorante sur la même cible.",
        requires = "Tu connais Peste dévorante (niveau 20). Tous les Prêtres l'ont dans Forever, avec 24 s de recharge.", mods = { "Mot de l’ombre : Douleur sur la cible survolée, puis sur ta cible", "Peste dévorante sur la cible survolée, puis sur ta cible" } },
      ["pvp-elunes-grace"] = { title = "Grâce d'Elune, Shift pour un bouclier", use = "Annule ton incantation et utilise Grâce d'Elune quand un joueur de mêlée ou un Chasseur se retourne contre toi. Maintiens Shift pour te mettre plutôt un bouclier.",
        requires = "Prêtre elfe de la nuit. Grâce d'Elune est un sort racial des Elfes de la nuit (niveau 20, 5 min de recharge). Celle de Forever réduit de 50 % les chances que les attaques en mêlée et à distance te touchent, pendant 15 s ou jusqu'à trois ratés. Celle de Classic réduisait les dégâts à distance et ajoutait de l'esquive.", mods = { "Arrêter l'incantation, Grâce d'Elune", "Arrête ton incantation, bouclier sur toi" } },
      ["pvp-emergency-heal"] = { title = "Arrêter et Soins rapides", use = "Annule ton incantation et lance Soins rapides sur la cible survolée, ta cible ou toi. Maintiens Shift pour te soigner.",
        requires = "Soins rapides appris", mods = { "Arrête ton incantation, soigne la cible survolée, ta cible ou toi", "Arrête ton incantation, soigne-toi" } },
      ["pvp-feedback"] = { title = "Arrêter et Réaction", use = "Annule ton incantation et lève Réaction. Pendant 15 s, chaque sort qui te touche brûle une partie du mana du lanceur et lui inflige des dégâts d'Ombre pour chaque point brûlé.",
        requires = "Prêtre humain. Réaction est un sort racial des Humains dans Forever (niveau 20, 3 min de recharge). Le rang 1 brûle 18 points de mana par sort.", mods = {  } },
      ["pvp-flash-heal-enemy-target"] = { title = "Soins rapides via ta cible ennemie", use = "Soins rapides sur l’allié survolé ou ta cible amicale. Avec un ennemi en cible, ça soigne l’allié que cet ennemi poursuit, donc tu n’as jamais à lâcher l’ennemi.",
        requires = "Talent Holy Binding (Sacré), pour que la moitié de chaque Soins rapides sur un allié te soigne aussi", mods = {  } },
      ["pvp-flash-heal-party"] = { title = "Arrêter et Soins rapides, membre 1 ou 2 du groupe", use = "Annule ton incantation et lance Soins rapides sur l’allié survolé ou ta cible amicale. Shift soigne le membre 1 du groupe et Ctrl le membre 2, et Holy Binding te soigne de la moitié à chaque fois.",
        requires = "Talent Holy Binding (Sacré) pour le soin sur toi", mods = { "Arrêter l'incantation, Soins rapides sur la cible survolée, puis ta cible", "Arrêter l'incantation, Soins rapides sur le membre 1 du groupe", "Arrêter l'incantation, Soins rapides sur le membre 2 du groupe" } },
      ["pvp-flay-death"] = { title = "Fouet mental, Shift pour Mot de l'ombre : Mort", use = "Fouet mental sur ta cible hostile sans relancer la canalisation. Maintiens Shift pour arrêter la canalisation et achever l'ennemi survolé ou ta cible avec Mot de l’ombre : Mort.",
        requires = "Talent Fouet mental (Ombre, niveau 20) et tu connais Mot de l’ombre : Mort (niveau 32). Si Mot de l’ombre : Mort touche sans tuer, tu subis 30 % de ta vie max. Trépas prématuré (Ombre) ajoute du critique à 20 % de vie ou moins.", mods = { "Fouet mental sur ta cible hostile sauf si tu le canalises déjà", "Arrêter la canalisation, Mot de l’ombre : Mort sur la cible survolée, puis ta cible" } },
      ["pvp-flay-silence"] = { title = "Fouet mental, Shift pour Silence", use = "Fouet mental sur ta cible hostile sans relancer la canalisation. Maintiens Shift pour arrêter la canalisation et lancer Silence sur l'ennemi survolé ou ta cible : ton interruption tient sur ta touche de dégâts principale.",
        requires = "Talents Fouet mental et Silence (Ombre). Silence est au niveau 30, avec une portée de 20 mètres et 45 s de recharge.", mods = { "Fouet mental sur ta cible hostile sauf si tu le canalises déjà", "Arrêter la canalisation, Silence sur la cible survolée, puis ta cible" } },
      ["pvp-form-blast-or-heal"] = { title = "Attaque mentale en Forme d'Ombre, Soins rapides hors forme", use = "En Forme d'Ombre, elle lance Attaque mentale sur l'ennemi survolé ou ta cible. Hors Forme d'Ombre, la même touche lance Soins rapides sur l'allié survolé ou sur toi : un seul raccourci couvre les deux côtés du changement de forme.",
        requires = "Talent Forme d'Ombre (Ombre, niveau 40) et tu connais Soins rapides (niveau 20). Les macros de Classic comptent la Forme d'Ombre comme la forme 1. On ne l'a pas vérifié dans le client de Forever.", mods = {  } },
      ["pvp-hex-of-weakness"] = { title = "Maléfice de faiblesse sur la cible ou en mouseover", use = "Mets Maléfice de faiblesse sur ta cible, ce qui réduit sa puissance d'attaque en mêlée et les soins qu'elle reçoit. Maintiens Shift pour la cible survolée.",
        requires = "Prêtre troll. Maléfice de faiblesse est un sort racial des Trolls. Celui de Forever réduit la puissance d'attaque en mêlée. Celui de Classic réduisait les dégâts. La présentation de Blizzard du 30 septembre le dit inchangé ; les descriptions de notre copie du client et de Classic diffèrent.", mods = { "Maléfice sur ta cible", "Maléfice sur la cible survolée" } },
      ["pvp-holy-fire-nova"] = { title = "Flammes sacrées, Shift pour Nova sacrée", use = "Flammes sacrées sur l'ennemi survolé ou ta cible. Maintiens Shift pour Nova sacrée quand il s'approche ; Lumière incendiaire peut supprimer son coût après les ticks de dégâts sur la durée de Flammes sacrées.",
        requires = "Talents Nova sacrée et Lumière incendiaire (Sacré). Lumière incendiaire donne à chaque tick de Flammes sacrées une chance que ton prochain lancer de Nova sacrée ne coûte pas de mana.", mods = { "Flammes sacrées sur l'ennemi survolé, puis ta cible", "Nova sacrée autour de toi" } },
      ["pvp-holy-nova-sweep"] = { title = "Nova sacrée rang 1 pour débusquer, Shift pour le rang max", use = "Nova sacrée rang 1 touche les ennemis à 10 mètres pour peu de mana, assez pour faire sortir un Voleur ou un Druide proche de son Camouflage. Maintiens Shift pour arrêter ton incantation et utiliser ton meilleur rang comme soin de groupe rapide.",
        requires = "Talent Nova sacrée (Sacré). Le rang 1 coûte 185 points de mana ; celui du niveau 60 coûte 750.", mods = { "Nova sacrée rang 1", "Arrêter l'incantation, Nova sacrée au rang max" } },
      ["pvp-inner-focus-flash-heal"] = { title = "Arrêter, Focalisation améliorée et Soins rapides", use = "Annule ton incantation, active Focalisation améliorée et lance Soins rapides sur la cible survolée, ta cible amicale, la cible de ton ennemi ou toi. Shift te soigne. Avec Focalisation améliorée en recharge, tu as quand même le soin.",
        requires = "Talent Focalisation améliorée (Discipline, 3 min de recharge) et tu connais Soins rapides (niveau 20)", mods = { "Arrêter l'incantation, Focalisation améliorée, Soins rapides sur la cible survolée, ta cible, la cible de l'ennemi ou toi", "Arrêter l'incantation, Focalisation améliorée, Soins rapides sur toi" } },
      ["pvp-inner-focus-mana-burn"] = { title = "Focalisation améliorée avant Brûlure de mana", use = "Active Focalisation améliorée, puis lance Brûlure de mana gratuitement sur l'ennemi survolé ou ta cible. Sans ennemi à brûler, Focalisation améliorée attend ton prochain sort.",
        requires = "Talent Focalisation améliorée (Discipline) et tu connais Brûlure de mana (niveau 24). Brûlure de mana améliorée (Discipline) retire jusqu'à 1 s à son incantation de 3 s.", mods = {  } },
      ["pvp-inner-focus-mind-blast"] = { title = "Focalisation améliorée avant Attaque mentale", use = "Active Focalisation améliorée et lance Attaque mentale sur l'ennemi survolé ou ta cible : Attaque mentale sans coût en mana et avec plus de chances de critique. Une bonne ouverture sur un lanceur de sorts.",
        requires = "Talent Focalisation améliorée (Discipline, 3 min de recharge). Tu connais Attaque mentale (niveau 10).", mods = {  } },
      ["pvp-inner-focus-penance"] = { title = "Focalisation améliorée avant Pénitence", use = "Active Focalisation améliorée et lance Pénitence gratuitement sur la cible survolée, ta cible amicale, la cible de ton ennemi ou toi. Shift vise ta cible hostile. Rappuyer n'interrompt pas Pénitence en cours.",
        requires = "Talents Focalisation améliorée et Pénitence (Discipline). Pénitence rang 1 est au niveau 30, avec un temps de recharge de 12 s.", mods = { "Focalisation améliorée, soin de Pénitence sur la cible survolée, ta cible, la cible de l'ennemi ou toi", "Focalisation améliorée, dégâts de Pénitence sur ta cible hostile" } },
      ["pvp-litany-renew-flash"] = { title = "Alterner Rénovation et Soins rapides", use = "Alterne Rénovation et Soins rapides sur la cible survolée, ta cible amicale ou la cible de ton ennemi. Litanie de Lumière rend du mana quand chaque soin diffère du précédent, et Rénovation est instantané.",
        requires = "Talent Litanie de Lumière (Sacré) ; Holy Binding te soigne de la moitié de chaque Soins rapides. La séquence repart de zéro après 4 secondes sans appui.", mods = {  } },
      ["pvp-mending-enemy-target"] = { title = "Prière de guérison via ta cible ennemie", use = "Mets Prière de guérison sur l'allié survolé ou ta cible amicale. Avec un ennemi en cible, ça va sur l'allié que cet ennemi poursuit, ou sur toi. Alt te choisit toujours, pratique avant l'ouverture d'un Voleur.",
        requires = "Talent Prière de guérison (Sacré) ; le rang 1 est au niveau 40 dans le client, avec 10 s de recharge. Tu ne peux en avoir qu'un actif à la fois.", mods = { "Guérison sur la cible survolée, ta cible, la cible de ton ennemi, puis toi", "Guérison sur toi" } },
      ["pvp-mind-flay-rank-1"] = { title = "Fouet mental rang 1 pour ralentir, Shift pour le rang max", use = "Fouet mental rang 1 ralentit ta cible hostile de 50 % pour une fraction du mana, et c'est souvent tout ce qu'il faut pour kiter un joueur de mêlée. Maintiens Shift pour ton meilleur rang. Aucun des deux ne relance une canalisation en cours.",
        requires = "Talent Fouet mental (Ombre, niveau 20). Le rang 1 coûte 45 points de mana ; celui du niveau 60 coûte 205.", mods = { "Fouet mental rang 1 sur ta cible hostile", "Fouet mental au rang max sur ta cible hostile" } },
      ["pvp-mind-flay-slow"] = { title = "Fouet mental pour ralentir, sur la cible ou en mouseover", use = "Fouet mental sur ta cible sans relancer la canalisation. Maintiens Shift pour ralentir plutôt la cible survolée.",
        requires = "Talent Fouet mental (Ombre, niveau 20). Il ralentit la cible de 50 % ; depuis le 15 octobre, Fouet mental amélioré rend plutôt chaque tick plus puissant.", mods = { "Fouet mental sur ta cible", "Fouet mental sur la cible survolée" } },
      ["pvp-nearest-enemy-pain"] = { title = "Ennemi le plus proche, puis Mot de l'ombre : Douleur", use = "Prend l'ennemi le plus proche si tu n'as pas de cible hostile vivante, puis pose Mot de l’ombre : Douleur dessus.",
        requires = "", mods = {  } },
      ["pvp-pain-rank-1"] = { title = "Mot de l'ombre : Douleur rang 1 sur les furtifs", use = "Pose un Mot de l’ombre : Douleur rang 1 peu coûteux sur l'ennemi survolé ou ta cible. Ses ticks brisent le Camouflage, donc un Voleur ou un Druide a du mal à s'échapper tant qu'il est actif.",
        requires = "Tu connais Mot de l’ombre : Douleur. Le rang 1 coûte 25 points de mana et dure 18 s. Il ne remplace pas un rang plus élevé que tu as déjà posé sur la cible.", mods = {  } },
      ["pvp-penance-enemy-target"] = { title = "Pénitence sur un ennemi, Shift pour soigner sa cible", use = "Pénitence sur l'ennemi survolé ou ta cible. Maintiens Shift pour soigner plutôt l'allié que poursuit ton ennemi ciblé, sans le quitter. Rappuyer n'interrompt pas Pénitence en cours.",
        requires = "Talent Pénitence (Discipline). Le rang 1 est au niveau 30, avec 12 s de recharge.", mods = { "Dégâts de Pénitence sur l'ennemi survolé, puis ta cible", "Soin de Pénitence sur la cible de ton ennemi si c'est un allié" } },
      ["pvp-power-infusion-party"] = { title = "Infusion de puissance sur le membre 1 ou 2 du groupe", use = "Infusion sur l'allié survolé ou ta cible. Shift la donne au membre du groupe 1, Ctrl au membre 2 et Alt à toi, pour la passer à ton caster sans changer de cible.",
        requires = "Talent Infusion de puissance (Discipline, niveau 40). Son temps de recharge est de 3 min.", mods = { "Infusion sur la cible survolée, puis ta cible amicale, puis toi", "Infusion sur le membre du groupe 1", "Infusion sur le membre du groupe 2", "Infusion sur toi" } },
      ["pvp-scream-fade"] = { title = "Cri psychique, Shift pour Oubli", use = "Annule ton incantation en cours, puis lance Cri psychique sur les ennemis autour de toi. Maintiens Shift pour Oubli à la place. Le guide de Blizzard du 30 septembre dit que la réduction de menace de Oubli est doublée.",
        requires = "", mods = { "Arrêter l'incantation, Cri psychique", "Arrêter l'incantation, Oubli" } },
      ["pvp-shadow-protection"] = { title = "Protection contre l'Ombre, Shift pour le groupe", use = "Donne la résistance à l'Ombre à la cible survolée, ta cible ou toi. Maintiens Shift pour Prière de protection contre l'Ombre.",
        requires = "Tu connais Protection contre l'Ombre (niveau 30). Prière de protection contre l'Ombre arrive au niveau 56, et l'infobulle de Forever couvre tous les membres du groupe et du raid.", mods = { "Protection contre l'Ombre sur la cible survolée, ta cible ou toi", "Prière de protection contre l'Ombre" } },
      ["pvp-shadowform-flay"] = { title = "Fouet mental qui remet la Forme d'Ombre", use = "Hors de Forme d’Ombre, le premier appui la remet. En forme, la même touche lance Fouet mental sur l'ennemi survolé ou ta cible sans relancer la canalisation. Pratique après avoir quitté la forme pour soigner.",
        requires = "Talents Forme d’Ombre et Fouet mental (Ombre) ; Forme d’Ombre est au niveau 40 et coûte 40 % du mana de base à chaque fois. Les macros de Classic comptent Forme d’Ombre comme la forme 1. On ne l'a pas vérifié dans le client de Forever.", mods = {  } },
      ["pvp-shield-party"] = { title = "Bouclier sur le membre 1 ou 2 du groupe, ou sur la cible de ton ennemi", use = "Pose un bouclier sur l'allié survolé ou ta cible amicale. Si tu cibles un ennemi, elle protège l'allié que cet ennemi cible, ou toi. Shift protège le membre du groupe 1 et Ctrl le membre 2.",
