      ["enhancement-weapon-imbue"] = { title = "Choisis ton enchantement d'arme", use = "Appuie pour Arme Furie-des-vents, ou maintiens Shift pour Langue de feu, Ctrl pour Arme de givre ou Alt pour Croque-roc. La ligne /use 16 clique sur ta main droite.",
        requires = "Arme Furie-des-vents appris au niveau 30. On n'a pas encore vu comment Forever choisit l'arme : supprime /use 16 si l'enchantement s'applique sans.", mods = { "Arme Furie-des-vents", "Arme Langue de feu", "Arme de givre", "Arme Croque-roc" } },
      ["pvp-bolt-fake-cast"] = { title = "Éclair avec annulation sur Shift", use = "Commence Éclair pour attirer une interruption et appuie avec Shift pour l’annuler. Une interruption sur Éclair bloque tes sorts de Nature, soins compris, alors fais-la gaspiller.",
        requires = "", mods = { "Éclair", "Annule le sort en cours d'incantation" } },
      ["pvp-bolt-flame-shock"] = { title = "Éclair avec Horion de flammes sur la même touche", use = "Lance Éclair sur ta cible. Ctrl pose Horion de flammes sur ta cible et Shift sur ton mouseover, pour garder une brûlure sur leur soigneur pendant que tu incantes.",
        requires = "Horion de flammes appris", mods = { "Éclair sur ta cible", "Horion de flammes sur la cible survolée", "Horion de flammes sur ta cible" } },
      ["pvp-dispel-key"] = { title = "Expiation sur les ennemis et guérison des alliés sur une touche", use = "Purge un ennemi, guérit le poison d'un allié, et Shift guérit sa maladie, en visant d'abord la cible survolée, puis ta cible.",
        requires = "", mods = { "Guérison du poison sur un allié ou Expiation sur un ennemi", "Guérison des maladies sur un allié" } },
      ["pvp-earthbind-root"] = { title = "Arrête l'incantation et immobilise la mêlée avec Lien à la terre", use = "Quand la mêlée t'atteint en pleine incantation, la macro annule le sort et pose Totem de lien terrestre, qui immobilise les ennemis proches pendant 5 s avec Lien terrestre. Shift lance plutôt Horion de givre sur ton mouseover ou ta cible.",
        requires = "Talent Lien terrestre pour l'immobilisation ; sans lui, Lien à la terre ne fait que ralentir", mods = { "Arrête l'incantation et pose Totem de lien terrestre", "Arrête l'incantation et lance Horion de givre sur ton mouseover ou ta cible" } },
      ["pvp-elemental-mastery-burst"] = { title = "Maîtrise de la foudre, bijoux et Éclair", use = "Déclenche Maîtrise de la foudre, tes deux bijoux et ton trait racial d’Orc ou de Troll, puis commence Éclair, ou Chaîne d’éclairs avec Shift. Pendant 15 s, Éclair s’incante 0.5 s plus vite et Chaîne d’éclairs n’a pas de temps de recharge.",
        requires = "Talent Maîtrise de la foudre ; Chaîne d’éclairs (32) pour Shift. Fureur sanguinaire est pour les Orcs et Berserker pour les Trolls ; pour les autres races, ces lignes échouent, tout simplement. Si Maîtrise est en recharge, l'incantation démarre quand même.", mods = { "Temps de recharge, puis Éclair", "Temps de recharge, puis Chaîne d’éclairs" } },
      ["pvp-flame-shock-rank-1"] = { title = "Horion de flammes rang 1 contre le camouflage", use = "Un Horion de flammes rang 1, peu coûteux, sur ton mouseover ou ta cible. La brûlure garde un Voleur ou un Druide en combat et brise le camouflage à chaque tick : il ne peut pas se cacher avant qu'elle se dissipe.",
        requires = "", mods = {  } },
      ["pvp-flame-shock-spread"] = { title = "Horion de flammes sur la cible, le mouseover ou la dernière cible", use = "Horion de flammes sur ta cible, ton mouseover avec Shift ou ta dernière cible avec Ctrl, puis reviens, pour répartir tes dégâts sur la durée pendant un combat.",
        requires = "Ctrl passe sur ta dernière cible puis revient, il faut donc une dernière cible à portée", mods = { "Horion de flammes sur ta cible", "Horion de flammes sur la cible survolée", "Horion de flammes sur ta dernière cible, puis reviens" } },
      ["pvp-friend-target-shock"] = { title = "Horion ou Expiation sur l'ennemi que combat ton allié", use = "Garde un allié en cible pour le soigner et interromps quand même : Horion de terre rang 1 sur ton mouseover, ou sur l'ennemi qu'attaque ta cible amie. Shift lance Expiation sur le même ennemi.",
        requires = "Expiation appris au niveau 12. Annule ton incantation en cours.", mods = { "Horion de terre rang 1 sur le mouseover ou la cible de ton allié", "Expiation sur le mouseover ou la cible de ton allié" } },
      ["pvp-grounding-tremor-now"] = { title = "Annule ton incantation pour Glèbe ou Séisme", use = "Arrête le sort en cours pour que Totem de glèbe soit posé dès que tu vois une Métamorphose ou une Peur commencer. Shift pose plutôt Totem de Séisme quand un Démoniste ou un Prêtre s'apprête à lancer une Peur.",
        requires = "Totem de glèbe appris au niveau 30. Un appui annule quand même ton incantation pendant le temps de recharge du Totem de glèbe.", mods = { "Arrête l'incantation et pose Totem de glèbe", "Arrête l'incantation et pose Totem de Séisme" } },
      ["pvp-heal-fast"] = { title = "Soin rapide qui annule le loup", use = "Quitte Loup fantôme et lance Vague de soins inférieurs sur ton mouseover ou ta cible, ou sur toi si tu maintiens Alt ou si tu n'as personne en cible.",
        requires = "", mods = { "Vague de soins inférieurs sur le mouseover, la cible ou toi", "Vague de soins inférieurs sur toi" } },
      ["pvp-heal-their-target"] = { title = "Soigner la cible de ta cible ennemie", use = "Garde l'ennemi sélectionné et soigne l'allié qu'il attaque : Vague de soins inférieurs, Shift pour Vague de soins, Ctrl pour Salve de guérison ou Alt pour Remous.",
        requires = "Une cible ennemie qui attaque un allié. Salve de guérison s'apprend au niveau 40 et Remous est un talent.", mods = { "Vague de soins inférieurs sur la cible de ton ennemi", "Vague de soins sur la cible de ton ennemi", "Salve de guérison sur la cible de ton ennemi", "Remous sur la cible de ton ennemi" } },
      ["pvp-interrupt-earth-shock"] = { title = "Interromps avec Horion de terre rang 1", use = "Te fait descendre de monture, arrête ton incantation et interrompt avec Horion de terre rang 1 : ta cible, ton mouseover avec Shift ou ta dernière cible avec Ctrl.",
        requires = "Ctrl passe sur ta dernière cible, lance l'horion, puis revient, il faut donc une dernière cible à portée", mods = { "Horion de terre rang 1 sur ta cible", "Horion de terre rang 1 sur ton mouseover", "Horion sur ta dernière cible, puis retour" } },
      ["pvp-lesser-heal-party"] = { title = "Vague de soins inférieurs sur ton groupe au clavier", use = "Soin rapide sur la cible survolée, ta cible amicale ou toi, ou sur les membres du groupe 1, 2 et 3 avec Shift, Ctrl et Alt, pour garder les yeux sur le combat plutôt que sur les cadres.",
        requires = "", mods = { "Vague de soins inférieurs sur le mouseover, la cible amie ou toi", "Vague de soins inférieurs sur le membre du groupe 1", "Vague de soins inférieurs sur le membre du groupe 2", "Vague de soins inférieurs sur le membre du groupe 3" } },
      ["pvp-mana-tide-potion"] = { title = "Totem de vague de mana et une potion de mana en même temps", use = "Pose Totem de vague de mana et bois une potion de mana du même appui quand un long combat te vide. Avec 5 points de vie, le totem meurt au moindre dégât de zone : pose-le une fois sorti de la zone.",
        requires = "Talent Totem de vague de mana et son outil Totem d'eau. Remplace Potion de mana majeure par la potion que tu as sur toi.", mods = {  } },
      ["pvp-mastery-chain-lightning"] = { title = "Maîtrise de la foudre, puis Chaîne d’éclairs", use = "Maîtrise de la foudre supprime le temps de recharge de Chaîne d’éclairs pendant 15 s : la macro l'active et lance Chaîne d’éclairs sur ton mouseover ou ta cible. Continue d'appuyer dans un combat de groupe.",
        requires = "Talent Maîtrise de la foudre et Chaîne d’éclairs, appris au niveau 32", mods = {  } },
      ["pvp-melee-keys"] = { title = "Courroux naturel, Horion de terre et Horion de givre en mêlée", use = "Courroux naturel pour ouvrir, Shift pour Horion de terre avec son bonus de 20 % et Ctrl pour ralentir avec Horion de givre ; chacun lance ton attaque auto.",
        requires = "Talent Courroux naturel. C'est un talent à 16 point, donc tu peux le prendre au niveau 25 (Blizzard, 7 octobre).", mods = { "Courroux naturel", "Horion de terre", "Horion de givre" } },
      ["pvp-nuke-picker"] = { title = "Éclair ou Chaîne d'éclairs sur la cible ou le mouseover", use = "Éclair sur ta cible, Shift pour ton mouseover, et Ctrl ou Alt pour Chaîne d’éclairs sur ta cible ou ton mouseover.",
        requires = "", mods = { "Éclair sur ta cible", "Éclair sur la cible survolée", "Chaîne d’éclairs sur ta cible", "Chaîne d’éclairs sur la cible survolée" } },
      ["pvp-projection-fire-nova"] = { title = "Ramène tes totems vers toi, puis Nova de feu", use = "Shift lance Appel totémique, qui déplace tes totems là où tu te tiens. Un appui simple déclenche Nova de feu sur ton totem de feu : tu peux emmener le Totem de Magma au milieu d’un groupe et le faire exploser.",
        requires = "Un totem de feu posé pour Nova de feu. Appel totémique a 30 s de temps de recharge.", mods = { "Nova de feu autour de ton totem de feu", "Appel totémique : tes totems viennent à toi" } },
      ["pvp-riptide-chain-heal"] = { title = "Remous, ou Salve de guérison sur le même allié", use = "Remous sur ton mouseover, ta cible ou toi, et Shift lance Salve de guérison sur le même allié, 25 % plus efficace sur une cible sous Remous.",
        requires = "Talent Remous et Salve de guérison appris", mods = { "Remous sur le mouseover, la cible ou toi", "Salve de guérison sur le mouseover ou la cible" } },
      ["pvp-riptide-now"] = { title = "Remous instantané qui annule le loup et ton incantation", use = "Quitte Loup fantôme, annule le soin en cours et lance Remous sur ton mouseover, ta cible amie ou toi. Shift et Ctrl l'envoient sur le premier et le deuxième membre de ton groupe.",
