      ["pvp-slow-frost-shock"] = { title = "Ralentis un fuyard avec Horion de givre", use = "Horion de givre ralentit ta cible de 50 % ; Shift ralentit ton mouseover et Ctrl lance le rang 1, peu coûteux, sur ta cible.",
