      ["pvp-stick-earthbind"] = { title = "Lien à la terre ou Horion de givre et continue de frapper", use = "Pose Totem de lien terrestre à tes pieds pour qu'une cible qui kite ne puisse pas sortir de la mêlée, ou Shift lance Horion de givre sur ta cible. Les deux lancent ton attaque auto, et Emprise de la terre élargit la portée du totem.",
        requires = "", mods = { "Totem de lien terrestre et lance l'attaque auto", "Horion de givre sur ta cible et lance l'attaque auto" } },
      ["pvp-stormstrike-cooldowns"] = { title = "Courroux naturel, avec Ctrl pour ajouter tes temps de recharge", use = "Un appui simple lance ton attaque auto et Frappe-tempête. Maintiens Ctrl quand tu vas chercher le kill pour ajouter Rage long-voyante et tes deux bijoux sur le même appui.",
        requires = "Talents Courroux naturel et Rage long-voyante", mods = { "Lance l'attaque auto et Courroux naturel", "Rage long-voyante et tes deux bijoux, puis Courroux naturel" } },
      ["pvp-stormstrike-mouseover"] = { title = "Courroux naturel et Horion de terre sur ton mouseover", use = "Courroux naturel sur l'ennemi sous ton curseur, par exemple un soigneur à côté de ta cible, et Shift enchaîne avec Horion de terre sur le même ennemi tant que son bonus de 20 % est actif. Sans mouseover, les deux touchent ta cible.",
