      ["pvp-swap-imbue"] = { title = "Enchantement pour l'arme en main", use = "Arme Furie-des-vents sur ton arme à deux mains, ou Arme de givre quand tu portes un bouclier : ses ralentissements t'aident à tenir les ennemis à distance pendant que tu te défends.",
