      ["pvp-swift-heal-party"] = { title = "Vague de soins sous Rapidité de la nature sur un membre du groupe", use = "Arrête ton incantation, puis Rapidité de la nature te permet de lancer Vague de soins en instantané sur ton mouseover, ta cible amie ou toi. Shift et Ctrl l'envoient sur les membres du groupe 1 et 2, Alt sur toi.",
