      ["pvp-swift-nuke"] = { title = "Rapidité de la nature pour un nuke instantané", use = "Rapidité de la nature rend le prochain sort instantané : Éclair sur ton ennemi, Chaîne d’éclairs avec Shift ou Vague de soins sur toi avec Alt.",
        requires = "Talent Rapidité de la nature. S'il est en recharge, le sort s'incante normalement.", mods = { "Éclair en instantané sur ta cible ennemie", "Chaîne d’éclairs en instantané", "Vague de soins en instantané sur toi" } },
      ["pvp-totem-control"] = { title = "Glèbe, Séisme, Lien à la terre et Griffes de pierre sur une touche", use = "Totem de glèbe détourne un sort nuisible qui vise un membre du groupe proche, et Shift, Ctrl et Alt posent plutôt Séisme, Lien à la terre et Griffes de pierre.",
        requires = "", mods = { "Totem de glèbe", "Totem de Séisme", "Totem de lien terrestre", "Totem de Griffes de pierre" } },
      ["pvp-trinket-racial"] = { title = "Bijoux et trait racial défensif sur une touche", use = "Utilise ton trait racial d'évasion et tes deux bijoux en même temps quand tu es étourdi ou en difficulté.",
        requires = "Tauren (Choc martial), Nain (Forme de pierre) ou Orc (Bris de malédictions). Les lignes des autres races échouent, tout simplement.", mods = {  } },
      ["pvp-weapon-swap"] = { title = "Arme à deux mains, ou arme à une main et bouclier", use = "Équipe ton arme à deux mains pour Frappe-tempête et Furie-des-vents, ou avec Shift ton arme à une main et ton bouclier quand la mêlée ou les Chasseurs te focus. Remplace les trois emplacements réservés par les noms de tes objets.",
        requires = "Une arme à deux mains, une arme à une main et un bouclier dans tes sacs. Les enchantements restent sur l'arme où tu les as lancés : enchante les deux avant le combat.", mods = { "Équipe ton arme à deux mains", "Équipe ton arme à une main et ton bouclier" } },
      ["pvp-wolf-shock"] = { title = "Entrer et sortir de Loup fantôme, ou en sortir avec un horion", use = "Appuie pour activer ou quitter Loup fantôme ; maintiens Shift pour quitter le loup et lancer Horion de givre sur ta cible d'un seul appui.",
        requires = "Loup fantôme ne fonctionne qu'en extérieur tant que tu n'as pas pris Loup fantôme amélioré", mods = { "Active Loup fantôme, ou en sort si tu es déjà en loup", "Quitte le loup et lance Horion de givre sur ta cible" } },
      ["pvp-wolf-stormstrike"] = { title = "Arrive en Loup fantôme, sors-en avec Courroux naturel", use = "Shift te transforme en Loup fantôme pour combler la distance. Un appui simple quitte le loup, lance l'attaque auto et Frappe-tempête d'un coup.",
        requires = "Talent Courroux naturel. Loup fantôme amélioré réduit jusqu'à 3 s l'incantation du loup et permet de l'utiliser en intérieur.", mods = { "Quitte Loup fantôme, lance l'attaque auto et Courroux naturel", "Loup fantôme" } },
      ["restoration-ancestral-spirit"] = { title = "Ressuscite le mouseover ou la cible", use = "Ressuscite le joueur mort sous ton curseur, ou ta cible morte, une fois hors combat.",
