      ["restoration-chain-heal"] = { title = "Salve de guérison en mouseover", use = "Salve de guérison sur ton mouseover, ta cible ou toi. En groupe, il ne rebondit que sur les autres membres du groupe.",
        requires = "", mods = {  } },
      ["restoration-heal-or-bolt"] = { title = "Vague de soins sur les alliés, Éclair sur les ennemis", use = "Soigne une cible amicale, lance un éclair sur un ennemi, te soigne si rien n'est sélectionné, et Alt te soigne quelle que soit ta cible.",
        requires = "", mods = { "Vague de soins sur un allié, Éclair sur un ennemi", "Vague de soins sur toi" } },
      ["restoration-healing-wave"] = { title = "Vague de soins en mouseover", use = "Soigne l'allié survolé, ta cible ou toi-même.",
        requires = "", mods = {  } },
      ["restoration-healing-wave-downrank"] = { title = "Petit soin avec un rang inférieur de Vague de soins", use = "Appuie pour le rang maximum de Vague de soins, ou maintiens Shift pour le rang 4, moins cher, quand un petit soin suffit.",
