      ["restoration-nature-swiftness-heal"] = { title = "Rapidité de la nature pour un soin instantané", use = "Rapidité de la nature rend ton prochain soin instantané : la macro lance Vague de soins, ou Salve de guérison avec Shift, sur ton mouseover, ta cible ou toi.",
        requires = "Talent Rapidité de la nature. S'il est en recharge, tu lances une incantation normale.", mods = { "Vague de soins en instantané", "Salve de guérison en instantané" } },
      ["restoration-riptide"] = { title = "Remous en mouseover", use = "Utilise le nouveau talent Restauration de Forever sur le cadre de groupe sous ton curseur.",
