      ["restoration-riptide-chain-heal"] = { title = "Remous, puis Salve de guérison sur le même allié", use = "Remous au premier appui et Salve de guérison au suivant, 25 % plus efficace sur une cible sous Remous : garde ton curseur sur le même allié.",
