      ["restoration-utility-totems"] = { title = "Purification du poison, Purification des maladies ou Totem de séisme", use = "Totem de Purification du poison, ou Shift pour Totem de Purification des maladies et Ctrl pour Totem de Séisme, qui dissipe Peur, Charme et Sommeil.",
