      ["restoration-water-totems"] = { title = "Guérisseur, Fontaine de mana ou Totem de vague de mana", use = "Totem guérisseur soigne le groupe, Shift pose Totem Fontaine de mana et Ctrl pose Totem de vague de mana quand le mana vient à manquer.",
        requires = "Talent Totem de vague de mana pour Ctrl, et son outil Totem d'eau. C'est un talent à 16 point, donc tu peux le prendre au niveau 25 (Blizzard, 7 octobre).", mods = { "Totem guérisseur", "Totem Fontaine de mana", "Totem de vague de mana" } },
