        requires = "Talent Présence spirituelle et Contresort (24). Quand Présence spirituelle est en recharge, le mouton s'incante normalement. Si tu coupes une incantation que tu venais de lancer, appuie à nouveau.", mods = {  } },
      ["pvp-dismount-pyro-opener"] = { title = "Descendre de monture et ouvrir à l'Explosion pyrotechnique avec les bijoux", use = "Hors combat, un appui te fait descendre de ta monture, active tes deux bijoux et lance Explosion pyrotechnique sur ta cible. Une fois en combat, la même touche lance Trait de feu.",
        requires = "Talent Explosion pyrotechnique ; des bijoux activables pour les lignes de bijoux", mods = {  } },
      ["pvp-fire-blast-pyro"] = { title = "Trait de feu, puis une Explosion pyrotechnique plus rapide", use = "Le premier appui lance Trait de feu, qui ajoute un cumul de Réchauffement à l'impact (deux sur un critique), donc Explosion pyrotechnique à l'appui suivant s'incante au moins 25 % plus vite. Maintiens Shift pour ajouter Combustion.",
        requires = "Talents Réchauffement et Explosion pyrotechnique ; Combustion (40) pour Shift. Tant que Trait de feu est en recharge, le premier appui ne fait rien.", mods = { "Trait de feu, puis Explosion pyrotechnique à l'appui suivant", "Combustion aussi" } },
      ["pvp-frostbolt-ice-lance"] = { title = "Éclair de givre, puis Javelot de glace à l'impact", use = "Sur une cible gelée, appuie une fois pour Éclair de givre et encore juste avant l'impact pour Javelot de glace, pour que les deux touchent tant que le gel tient. Une nouvelle cible ou 4 s d'inactivité réinitialise la séquence.",
        requires = "Talent Javelot de glace. Nova de givre, Morsure de givre ou Doigts de givre te donnent le gel, et Javelot de glace frappe bien plus fort une cible gelée. Son temps de recharge de 8 s est partagé avec Trait de feu.", mods = {  } },
      ["pvp-frostbolt-kite"] = { title = "Éclair de givre pour ralentir, Cône de froid quand ils approchent", use = "Lance Éclair de givre sur l’ennemi sous ton curseur, ou sur ta cible. Shift lance le rang 1, une incantation de 1.5 s avec un ralentissement plus court. Ctrl annule ton incantation pour Cône de froid, qui frappe plus fort grâce à tes cumuls de Froid hivernal.",
        requires = "Cône de froid (26) pour Ctrl", mods = { "Éclair de givre sur la cible survolée, ou sur ta cible", "Éclair de givre rang 1 sur le même ennemi", "Arrêter l'incantation, puis Cône de froid" } },
      ["pvp-frostfire-slow"] = { title = "Éclair de givrefeu en mouseover, Éclair de givre rang 1 sur Shift", use = "Lance Éclair de givrefeu sur l’ennemi sous ton curseur, ou sur ta cible, ce qui laisse une brûlure et un ralentissement. Shift lance plutôt Éclair de givre rang 1, une incantation de 1.5 s, quand il te faut le ralentissement plus tôt.",
        requires = "Éclair de givrefeu, que le maître enseigne au niveau 40. Les critiques de Éclair de givrefeu font aussi monter Réchauffement.", mods = { "Éclair de givrefeu sur la cible survolée, ou sur ta cible", "Éclair de givre rang 1 sur le même ennemi" } },
      ["pvp-ice-block-exit"] = { title = "Sortir du Bloc de glace avec Transfert, Barrière de glace ou Javelot de glace", use = "Annule Bloc de glace et s'éloigne avec Transfert. Shift en sort plutôt avec Barrière de glace, et Ctrl avec Javelot de glace sur ta cible. Si seul le Bloc tombe, appuie à nouveau.",
        requires = "Talent Bloc de glace ; talents Barrière de glace (40) et Javelot de glace pour les modificateurs. Le sort qui suit l'annulation demande parfois ce second appui.", mods = { "Annuler Bloc de glace, puis Transfert", "Annuler Bloc de glace, puis Barrière de glace", "Annuler Bloc de glace, puis Javelot de glace sur ta cible" } },
      ["pvp-mana-shield-gem"] = { title = "Bouclier de mana, avec une gemme de mana sur Shift", use = "Annule ton incantation et active Bouclier de mana. Maintiens Shift pour utiliser d'abord une gemme de mana, car le bouclier draine du mana à chaque coup qu'il absorbe.",
        requires = "Bouclier de mana (20), et une gemme invoquée pour Shift. Sauvegarde des arcanes réduit d'un tiers le mana dépensé par point de dégâts. Les noms d'objets sont ceux de Classic.", mods = { "Lancer Bouclier de mana", "Utiliser une gemme de mana, puis lancer Bouclier de mana" } },
      ["pvp-missile-barrage"] = { title = "Projectiles des arcanes sur proc de Barrage de projectiles", use = "Quand Barrage de projectiles s'allume, cette macro abandonne ta Boule de feu ou ton Éclair de givre et tire des Projectiles des arcanes rapides et gratuits sur l'ennemi sous ton curseur ou sur ta cible. Marteler la touche ne relance pas la canalisation.",
        requires = "Talent Barrage de projectiles. Un sort lancé il y a moins de 1.5 s bloque encore le temps de recharge global, donc les Projectiles des arcanes attendent.", mods = {  } },
      ["pvp-nova-pyro"] = { title = "Nova de givre, puis Explosion pyrotechnique pendant l'immobilisation", use = "Le premier appui gèle tout ce qui t'entoure. Sors de portée de mêlée et appuie à nouveau pour incanter Explosion pyrotechnique en entier avant la fin du gel. Ça se réinitialise après 8 s.",
        requires = "Talent Explosion pyrotechnique. La Nova tient jusqu'à 8 s et une incantation complète de Explosion pyrotechnique prend 6 s, donc les cumuls de Réchauffement te laissent de la marge. Ça n'annule pas une incantation en cours.", mods = {  } },
      ["pvp-nova-then-blink"] = { title = "Nova de givre, puis Transfert à l'appui suivant", use = "Le premier appui annule ton incantation et gèle tout ce qui t'entoure. Tourne-toi et appuie à nouveau pour t'éloigner avec Transfert. Après 8 s sans appui, ça repart sur la Nova.",
        requires = "Tu connais Nova de givre et Transfert (20). La séquence attend le temps de recharge de la Nova, alors garde aussi une touche Transfert simple.", mods = {  } },
      ["pvp-presence-arcane-wrath"] = { title = "Colère des arcanes instantanée, avec Pouvoir des arcanes sur Shift", use = "Avec Présence spirituelle, ton prochain lancer de Colère des arcanes part en instantané. Shift active aussi tes deux bijoux et Pouvoir des arcanes. Ça frappe le plus fort après quelques Déflagrations des arcanes.",
        requires = "Talents Présence spirituelle et Colère des arcanes (25), plus Pouvoir des arcanes pour Shift. Les trois sont dans l'arbre Arcanes.", mods = { "Présence spirituelle, puis Colère des arcanes en instantané", "Bijoux et Pouvoir des arcanes aussi, puis Colère des arcanes en instantané" } },
      ["pvp-pvp-burst"] = { title = "Burst : bijoux, Pouvoir des arcanes et Présence spirituelle", use = "Utilise tes deux bijoux, Pouvoir des arcanes et Présence spirituelle, puis lance Explosion pyrotechnique en instantané. Maintiens Shift pour Éclair de givre si tu n'as pas Explosion pyrotechnique.",
        requires = "Talents Pouvoir des arcanes et Présence spirituelle (Arcanes), plus le talent Explosion pyrotechnique (Feu) pour le sort par défaut", mods = { "Temps de recharge, puis Explosion pyrotechnique en instantané", "Temps de recharge, puis Éclair de givre en instantané" } },
      ["pvp-pvp-counterspell"] = { title = "Contresort sur ta cible, en mouseover ou suivi d'un sort", use = "Annule ton incantation et Bloc de glace, puis lance Contresort sur ta cible. Shift vise la cible survolée et Ctrl lance Éclair de givre juste après.",
        requires = "Tu connais Contresort (24). Ça annule ton incantation même quand Contresort est en recharge. Contresort ne déclenche pas le temps de recharge global, donc la ligne Éclair de givre peut suivre.", mods = { "Contresort sur ta cible", "Contresort sur la cible survolée à la place", "Contresort sur ta cible, puis lancer Éclair de givre" } },
      ["pvp-pvp-decurse-counter"] = { title = "Décurser un allié ou Contresort sur un ennemi sous le curseur", use = "Annule ton incantation, puis décurse l'allié sous ton curseur ou lance Contresort sur l'ennemi qui s'y trouve. Sans rien sous le curseur, elle utilise ta cible. Shift te décurse.",
        requires = "Tu connais Délivrance de la malédiction mineure (18) et Contresort (24). Ça annule ton incantation en cours.", mods = { "Décurser un allié survolé ou ciblé, ou Contresort sur un ennemi", "Décurse-toi" } },
      ["pvp-pvp-escape"] = { title = "Transfert, évasion raciale, bijoux et Potion de libre action", use = "Te fait descendre de monture, annule ton incantation et lance Transfert. Shift utilise plutôt ton évasion raciale, Ctrl ajoute tes deux bijoux à Transfert et Alt ajoute une Potion de libre action.",
        requires = "Tu connais Transfert (20). Les lignes raciales ne marchent que pour les Humains (Volonté de survie), les Gnomes (Maître de l'évasion) et les Morts-vivants (Volonté des Réprouvés).", mods = { "Transfert", "Utilise ton trait racial d'évasion", "Utiliser tes deux bijoux, puis Transfert", "Boire une Potion de libre action, puis Transfert" } },
      ["pvp-pvp-finisher"] = { title = "Trait de feu ou Javelot de glace en mouseover", use = "Annule ton incantation pour Trait de feu en instantané sur l’ennemi sous ton curseur, ou sur ta cible. Shift lance plutôt Javelot de glace, le meilleur coup sur une cible gelée. Les deux partagent 8 s de temps de recharge.",
        requires = "Tu connais Trait de feu ; talent Javelot de glace pour Shift. Ça annule ton incantation en cours.", mods = { "Trait de feu sur la cible survolée, ou sur ta cible", "Javelot de glace sur la cible survolée, ou sur ta cible" } },
      ["pvp-pvp-ice-block"] = { title = "Bloc de glace à bascule avec Morsure du froid sur Shift", use = "Lance Bloc de glace, et un second appui le retire plus tôt. Shift lance Morsure du froid pour terminer tes temps de recharge de givre, et l'appui suivant peut relancer le Bloc.",
        requires = "Talents Bloc de glace et Morsure du froid. Tant que Bloc de glace est en recharge, le second appui ne fait qu'annuler l'aura.", mods = { "Lancer Bloc de glace, ou l'annuler si l'effet est actif", "Annuler Bloc de glace si l'effet est actif, puis lancer Morsure du froid" } },
      ["pvp-pvp-peel"] = { title = "Peel : Nova de givre, Cône de froid et Vague explosive", use = "Te fait descendre de monture, annule ton incantation et Bloc de glace, puis lance Nova de givre rang 1, qui coûte moins et frappe bien moins fort (les dégâts peuvent briser le gel). Shift lance Cône de froid et Ctrl Vague explosive.",
        requires = "Tu connais Nova de givre ; Cône de froid (26) ; talent Vague explosive pour Ctrl", mods = { "Nova de givre rang 1", "Cône de froid", "Vague explosive" } },
      ["pvp-pvp-polymorph"] = { title = "Métamorphose en mouseover ou sur la cible, rang 1 sur Shift", use = "Annule ton incantation et métamorphose l'ennemi sous ton curseur, ou ta cible. Shift lance le rang 1, qui coûte moins de mana et dure moins longtemps.",
        requires = "Métamorphose appris", mods = { "Métamorphose sur la cible survolée, ou sur ta cible", "Lancer Métamorphose rang 1 sur le même ennemi" } },
      ["pvp-pvp-presence"] = { title = "Présence spirituelle et un sort instantané", use = "Utilise Présence spirituelle et lance un sort en instantané. Déflagration des arcanes par défaut, Shift pour Explosion pyrotechnique, Ctrl pour Métamorphose et Alt pour Éclair de givre.",
        requires = "Talent Présence spirituelle. Déflagration des arcanes et Explosion pyrotechnique demandent leur propre talent ; Métamorphose et Éclair de givre, non.", mods = { "Déflagration des arcanes en instantané", "Explosion pyrotechnique en instantané", "Métamorphose en instantané sur ta cible", "Éclair de givre en instantané" } },
      ["pvp-pvp-school-swap"] = { title = "Changer d'école après un verrouillage par Contresort", use = "Éclair de givre sur le bouton. Si un Contresort ennemi te bloque l'école de givre, Shift lance Boule de feu et Ctrl lance Projectiles des arcanes.",
        requires = "Éclair de givre, Boule de feu et Projectiles des arcanes appris", mods = { "Lancer Éclair de givre", "Lancer Boule de feu", "Lancer Projectiles des arcanes" } },
      ["pvp-pvp-sheep-and-back"] = { title = "Moutonner un second ennemi et sauter en arrière", use = "Passe à un deuxième ennemi avec Tab, appuie sur la macro pour le moutonner, et tu reviens aussitôt sur ta première cible.",
        requires = "Tu connais Métamorphose, et une cible précédente où revenir", mods = {  } },
      ["pvp-pvp-shields"] = { title = "Bouclier de mana, Barrière de glace et les deux Gardiens sur une touche", use = "Annule ton incantation et pose un bouclier. Bouclier de mana sur le bouton, Shift pour Barrière de glace, Ctrl pour Gardien de givre et Alt pour Gardien de feu.",
        requires = "Bouclier de mana (20), Gardien de feu (20), Gardien de givre (22) et le talent Barrière de glace (40)", mods = { "Bouclier de mana", "Barrière de glace", "Gardien de givre", "Gardien de feu" } },
      ["pvp-pvp-slow"] = { title = "Éclair de givre en mouseover pour le ralentir", use = "Lance Éclair de givre sur l'ennemi sous ton curseur, ou sur ta cible s'il n'y a personne. Shift lance le rang 1, moins cher, avec un ralentissement plus court.",
        requires = "Éclair de givre appris", mods = { "Éclair de givre sur la cible survolée, ou sur ta cible", "Lancer Éclair de givre rang 1 sur le même ennemi" } },
      ["pvp-pvp-trinkets"] = { title = "Bijoux sur une touche", use = "Utilise ton bijou du haut, Shift celui du bas et Ctrl les deux.",
        requires = "Des bijoux équipés dans les deux emplacements", mods = { "Utiliser ton bijou du haut", "Utiliser ton bijou du bas", "Utiliser tes deux bijoux" } },
      ["pvp-racial-burst"] = { title = "Bijoux et ton burst racial sur une touche", use = "Utilise tes deux bijoux et Berserker, Fureur sanguinaire ou Eurêka !, selon ta race. Appuie juste avant ton burst pour que tout s'aligne.",
        requires = "Les Trolls (Berserker), les Orcs (Fureur sanguinaire) et les Gnomes (Eurêka !) profitent des lignes raciales. Les autres races n'ont que les bijoux.", mods = {  } },
      ["pvp-shatter-cone"] = { title = "Fracasser avec Nova de givre, Éclair de givre et Cône de froid", use = "Appuie une fois pour geler ta cible et recule d'un pas, puis appuie pour Éclair de givre et encore pour Cône de froid. Chacun profite du bonus de critique de Fracasser tant que la cible reste gelée. Une nouvelle cible ou 8 s d'inactivité réinitialise la séquence.",
        requires = "Talent Fracasser pour les critiques ; Cône de froid (26). Les dégâts peuvent briser Nova de givre plus tôt, et le cumul de Froid hivernal de Éclair de givre s'ajoute au Cône.", mods = {  } },
      ["pvp-sheep-evocation"] = { title = "Moutonner, puis Évocation", use = "Le premier appui moutonne ta cible. Le second lance Évocation pendant qu'elle se promène, pour récupérer ton mana dans un long duel. Une nouvelle cible ou 20 s d'inactivité relance la séquence.",
