      ["demonology"] = { name = "Démonologie", tagline = "Un démon actif à chaque pull", why = {
        "Ton démon inflige 10 % de dégâts en plus, donc les combats tankés par le Marcheur du Vide vont plus vite.",
        "15 % des dégâts de tes sorts soignent ton démon, et Connexion lui donne le même mana que toi. Tu auras moins besoin de Captation de vie.",
