      ["affliction-drain-soul-mouseover"] = { title = "Siphon d'âme en mouseover", use = "Siphon d’âme sur ton mouseover ou ta cible pour tenter d'obtenir un Fragment d'âme, sans relancer une canalisation en cours.",
