      ["class-wide-armor-or-ward"] = { title = "Armure démoniaque, Shift pour Gardien de l'ombre", use = "Renouvelle Armure démoniaque, ou maintiens Shift pour Gardien de l'ombre avant des dégâts d'Ombre. Chaque appui ne lance que le sort que tu choisis.",
