      ["class-wide-curse-choice"] = { title = "Choisis ta malédiction avec une touche de modification", use = "Maudis ton mouseover ou ta cible avec Malédiction des éléments, ou maintiens un modificateur pour Faiblesse, Témérité ou Langages.",
