      ["class-wide-stones"] = { title = "Crée tes pierres avec un seul bouton", use = "Crée une Pierre de soins, ou maintiens un modificateur pour créer plutôt une Pierre d'âme, une Pierre de sort ou une Pierre de feu.",
        requires = "Chaque sort de Création appris (Pierre d'âme 18, Pierre de feu 28, Pierre de sort 36). Dans Forever, Pierre de feu et Pierre de sort s'appliquent à l'arme et se cumulent avec l'huile de sorcier", mods = { "Crée une Pierre de soins", "Crée une Pierre d'âme", "Crée une Pierre de sort", "Crée une Pierre de feu" } },
