      ["demonology-breath-and-sight"] = { title = "Respiration interminable et Détection de l'invisibilité", use = "Donne Respiration interminable à ton mouseover, ta cible amie ou toi, et maintiens Shift pour Détection de l'invisibilité à la place.",
