      ["demonology-health-funnel"] = { title = "Captation de vie, Shift pour arrêter", use = "Canalise sur ton démon vivant. Les appuis répétés ne relancent pas Captation de vie ; maintiens Shift pour arrêter quand ton familier a récupéré sa vie.",
