      ["demonology-sacrifice-resummon"] = { title = "Sacrifice, puis invoque un autre démon", use = "Sacrifie ton démon pour son effet de 2 h et invoques-en un autre aussitôt.",
        requires = "Talents Sacrifice démoniaque et Pacte démoniaque, avec un démon invoqué. Le Pacte demande 31 points en Démonologie, niveau 40 dans le planificateur ; on n'a pas testé quand il se débloque en jeu. Invoquer le démon que tu as sacrifié met fin à l'effet.", mods = { "Invoque ton Chasseur corrompu", "Invoque ton Diablotin", "Invoque ton Marcheur du Vide", "Invoque ta Succube" } },
      ["demonology-sayaad-summon"] = { title = "Invoque ta Succube ou ton Incube", use = "Invoque ta Succube, ou maintiens Shift pour l'Incube, qui a sa propre invocation dans Forever.",
