      ["destruction-bane-of-havoc"] = { title = "Plaie de tumulte en mouseover", use = "Pose Plaie de tumulte sur l'ennemi sous ton curseur, ou sur ta cible : 15 % des dégâts que tu infliges aux autres cibles le touchent aussi.",
        requires = "Talent Plaie de tumulte. Il prend l'emplacement de Plaie sur cet ennemi, donc Plaie d'agonie ne peut pas cohabiter avec", mods = {  } },
      ["destruction-conflagrate"] = { title = "Conflagration en mouseover", use = "Conflagration sur un mouseover qui porte ton Immolation, ou sur ta cible si tu ne survoles rien.",
