      ["destruction-hellfire-toggle"] = { title = "Lancer et arrêter Flammes infernales", use = "Lance Flammes infernales et appuie à nouveau pour l'arrêter, car le sort te brûle autant que les ennemis proches. Il peut infliger des coups critiques depuis la mise à jour du 1 octobre.",
