      ["destruction-shadow-bolt"] = { title = "Trait de l'ombre et attaque du familier", use = "Envoie ton démon sur l'ennemi en commençant Trait de l’ombre.",
        requires = "Un démon en vie pour l'ordre au familier", mods = {  } },
      ["destruction-shadow-bolt-imp"] = { title = "Trait de l'ombre avec un ordre Éclair de feu au Diablotin", use = "Lance Trait de l’ombre sur ta cible et demande un Éclair de feu sur l'ennemi actuel de ton Diablotin. La macro n'envoie pas le Diablotin sur une nouvelle cible et ne contourne ni son mana, ni son temps d'incantation, ni son temps de recharge.",
