      ["destruction-shadowburn"] = { title = "Brûlure de l'ombre en mouseover", use = "Achève un mouseover avec Brûlure de l'ombre : tu récupères un Fragment d'âme s'il meurt dans les 8 secondes.",
        requires = "Talent Brûlure de l'ombre et un Fragment d'âme pour le lancer", mods = {  } },
      ["pvp-amplify-exhaustion"] = { title = "Malédiction amplifiée, puis Malédiction de fatigue", use = "Annule ton incantation, active Malédiction amplifiée et ralentis ton mouseover ou ta cible avec Malédiction de fatigue. Si Malédiction amplifiée est en recharge, tu poses quand même le ralentissement.",
