      ["pvp-amplify-weakness"] = { title = "Malédiction amplifiée, puis Malédiction de faiblesse", use = "Active Malédiction amplifiée et pose Malédiction de faiblesse sur le Voleur ou le Guerrier qui te frappe, sur ton mouseover ou ta cible. Malédiction amplifiée renforce la malédiction de 50 %.",
        requires = "Talent Malédiction amplifiée (temps de recharge de 3 minutes). Dans Forever, Malédiction de faiblesse réduit les dégâts physiques infligés par l'ennemi. Tu n'as qu'une malédiction par ennemi : elle remplace Fatigue ou Langages", mods = {  } },
      ["pvp-assist-strike"] = { title = "Assiste, puis malédiction ou Plaie", use = "Assiste le joueur allié que tu cibles et ouvre avec Plaie d’agonie sur sa cible, ou une malédiction via un modificateur.",
        requires = "Un joueur allié en cible ; talent Malédiction de fatigue pour Ctrl", mods = { "Plaie d’agonie sur la cible de ton allié", "Malédiction des langages dessus", "Malédiction de fatigue dessus" } },
      ["pvp-bane-picker"] = { title = "Plaie de tumulte ou Plaie d'agonie sur une touche", use = "Pose Plaie de tumulte sur ton mouseover ou ta cible, par exemple leur soigneur : 15 % des dégâts que tu infliges aux autres ennemis le touchent aussi. Maintiens Shift pour Plaie d’agonie sur ta cible.",
        requires = "Talent Plaie de tumulte. Tumulte ne reste que sur un ennemi à la fois, et chaque ennemi ne porte qu'une Plaie de toi", mods = { "Plaie de tumulte sur la cible survolée ou ta cible", "Plaie d’agonie sur ta cible" } },
      ["pvp-burst-trinkets"] = { title = "Bijoux, trait racial et un nuke", use = "Utilise tes deux bijoux et ton trait racial d'Orc ou de Troll, puis lance Trait de l’ombre, ou un modificateur pour Conflagration ou Brûlure de l'ombre.",
        requires = "Bijoux à activation si tu en as ; Fureur sanguinaire (Orc) ou Berserker (Troll) selon ta race ; talents Conflagration et Brûlure de l'ombre pour les modificateurs", mods = { "Temps de recharge, puis Trait de l’ombre", "Temps de recharge, puis Conflagration", "Temps de recharge, puis Brûlure de l'ombre" } },
      ["pvp-coil-howl"] = { title = "Voile mortel ou Hurlement de terreur", use = "Annule ton incantation et lance Voile mortel sur ta cible, ou sur ton mouseover avec Shift, ou Hurlement de terreur avec Ctrl.",
