      ["pvp-conflag-daze"] = { title = "Lâche ton incantation et Conflagration sur un fuyard", use = "Annule ton incantation et lance Conflagration sur ta cible, ou sur ton mouseover avec Shift. Avec 5 points dans Conséquences, chaque Conflagration l'hébète et le ralentit de 50 % pendant 5 secondes.",
        requires = "Talent Conflagration et ton Immolation sur la cible ; Conséquences pour l'hébétement. Si tu appuies dans les 1.5 premières secondes d'une autre incantation, la macro annule seulement cette incantation", mods = { "Annule ton incantation et lance Conflagration sur ta cible", "Annule ton incantation et lance Conflagration sur ton mouseover" } },
      ["pvp-corruption-rank-1"] = { title = "Corruption rang 1 contre les camouflés", use = "Marque un Voleur ou un Druide sur ton mouseover ou ta cible avec Corruption rang 1, qui coûte 35 points de mana. Ses ticks le font sans cesse sortir du camouflage, et chacun peut quand même déclencher Crépuscule.",
        requires = "5 points dans Corruption amélioré, sinon c'est une incantation de 2 secondes. Un rang supérieur de ton propre Corruption déjà sur cet ennemi le bloque", mods = {  } },
      ["pvp-curse-swap"] = { title = "Malédiction des langages, de fatigue, de faiblesse ou des éléments", use = "Lance Malédiction des langages sur la cible survolée ou ta cible, ou maintiens un modificateur pour Épuisement, Faiblesse ou les Éléments.",
        requires = "Talent Malédiction de fatigue (niveau 25) ; Langages au niveau 26", mods = { "Malédiction des langages", "Malédiction de fatigue", "Malédiction de faiblesse", "Malédiction des éléments sur ta cible" } },
      ["pvp-decimation-soul-fire"] = { title = "Douleur brûlante, puis Feu de l'âme sous Décimation", use = "Maintiens Shift pour Douleur brûlante sur un ennemi sous 35 % de vie, puis appuie pour Feu de l'âme, que Décimation rend plus rapide et sans fragment pendant 10 secondes.",
        requires = "Talent Décimation et Feu de l'âme (niveau 48). À 2 points, Décimation réduit aussi de 90 % le temps de recharge de 1 minutes de Feu de l'âme. Trait de l'ombre le déclenche aussi", mods = { "Feu de l'âme sur ta cible", "Douleur brûlante sur ta cible" } },
      ["pvp-demonic-brand"] = { title = "Marque un ennemi avec Douleur brûlante pour ton démon", use = "Envoie ton démon sur ton mouseover ou ta cible et lance Douleur brûlante dessus : les prochains coups du démon sur cet ennemi infligent des dégâts de Feu ou d'Ombre supplémentaires.",
        requires = "Talent Marque démoniaque et un démon invoqué. La marque dure 10 secondes et couvre jusqu'à 6 attaques du familier à 3 points", mods = {  } },
      ["pvp-devour-magic"] = { title = "Dévorer la magie du Chasseur corrompu sur toi ou un allié", use = "Dévorer la magie sur ton mouseover ou ta cible, ou sur toi avec Shift.",
        requires = "Un Chasseur corrompu vivant", mods = { "Dévorer la magie sur ton mouseover, ou sur ta cible", "Dévorer la magie sur toi" } },
      ["pvp-devour-party"] = { title = "Dévorer la magie du Chasseur corrompu sur ton groupe", use = "Retire un effet magique du premier membre de ton groupe sans le cibler, ou maintiens un modificateur pour le deuxième, le troisième ou le quatrième. Dans un raid de champ de bataille, c'est ton propre groupe de cinq.",
        requires = "Un Chasseur corrompu vivant. Les membres du groupe sont numérotés dans l'ordre des cadres de groupe par défaut", mods = { "Dévorer la magie sur le premier membre de ton groupe", "Dévorer la magie sur le deuxième membre de ton groupe", "Dévorer la magie sur le troisième membre de ton groupe", "Dévorer la magie sur le quatrième membre de ton groupe" } },
      ["pvp-dot-spread"] = { title = "Répands tes DoT avec un seul bouton", use = "Pose Corruption sur ton mouseover ou ta cible, ou maintiens un modificateur pour Plaie d’agonie ou Siphon de vie.",
        requires = "Talent Siphon de vie (niveau 30). Plaie d’agonie peut être sur le même joueur qu'une malédiction", mods = { "Corruption", "Plaie d’agonie", "Siphon de vie" } },
      ["pvp-drain-swap"] = { title = "Drain de vie, Drain de mana ou Connexion", use = "Drain de vie sur ta cible sans relancer la canalisation, ou maintiens un modificateur pour un mouseover, Drain de mana ou Connexion.",
        requires = "Drain de mana appris (niveau 24). Blizzard a retiré Pacte noir, donc Alt lance Connexion", mods = { "Drain de vie sur ta cible", "Drain de vie sur la cible survolée", "Drain de mana sur ta cible", "Connexion, qui met aussi fin à une canalisation" } },
      ["pvp-fear-stop"] = { title = "Lâche ton incantation et Peur", use = "Annule ton incantation en cours, descends de ta monture et lance Peur sur ta cible, ou sur ton mouseover avec Shift.",
        requires = "Peur appris", mods = { "Annule ton incantation et lance Peur sur ta cible", "Peur sur la cible survolée à la place" } },
      ["pvp-felhunter-lock"] = { title = "Verrou magique, ou Domination corrompue pour un nouveau Chasseur corrompu", use = "Si ton Chasseur corrompu est invoqué, il lance Verrou magique sur l'ennemi qu'il combat, ou sur ton mouseover avec Shift. Sinon, la macro invoque un Chasseur corrompu, avec Domination corrompue d'abord en combat.",
        requires = "Talent Domination corrompue et Invocation d'un chasseur corrompu (niveau 30). Tout autre démon invoqué est remplacé. Chasseur corrompu amélioré réduit jusqu'à 6 secondes le temps de recharge de Verrou magique", mods = { "Verrou magique, ou invoque un Chasseur corrompu s'il n'est pas là", "Verrou magique sur ton mouseover" } },
      ["pvp-fire-burst"] = { title = "Burst Immolation, Conflagration, Brûlure de l'ombre", use = "Appuie trois fois pour Immolation, Conflagration et Brûlure de l'ombre sur ta cible, ou maintiens Shift pour commencer par Malédiction des éléments. Changer de cible fait tout repartir de zéro.",
        requires = "Talents Conflagration et Brûlure de l'ombre et un Fragment d'âme. Si Conflagration ou Brûlure de l'ombre est encore en recharge, l'appui ne fait rien tant qu'il n'est pas prêt", mods = { "Immolation, Conflagration, Brûlure de l'ombre", "Malédiction des éléments, puis les trois mêmes" } },
      ["pvp-funnel-or-sacrifice"] = { title = "Captation de vie, Shift pour sacrifier à la place", use = "Garde ton démon en vie avec Captation de vie sans relancer la canalisation. S'il meurt quand même, maintiens Shift pour le sacrifier et obtenir l'effet de 2 h.",
        requires = "Talent Sacrifice démoniaque et un démon vivant. Sans Pacte démoniaque, invoquer n'importe quel démon met fin à l'effet", mods = { "Captation de vie sur ton démon sans relancer la canalisation", "Sacrifice démoniaque" } },
      ["pvp-kite-dots"] = { title = "Séquence de DoT instantanés pour kiter", use = "Appuie en courant : Malédiction de fatigue, Corruption, Plaie d’agonie, puis Siphon de vie sur ta cible. Maintiens Shift pour commencer par Malédiction des langages sur un lanceur de sorts.",
        requires = "Talents Malédiction de fatigue et Siphon de vie, et 5 points dans Corruption amélioré pour lancer Corruption en instantané. Dans Forever, une Plaie et une Malédiction peuvent être sur le même ennemi. La séquence repart de zéro quand tu changes de cible ou quittes le combat", mods = { "Fatigue, puis Corruption, Plaie d’agonie et Siphon de vie", "Langages, puis Corruption, Plaie d’agonie et Siphon de vie" } },
      ["pvp-nightfall-bolt"] = { title = "Trait de l'ombre instantané quand Transe de l'ombre se déclenche", use = "Quand Transe de l'ombre s'allume, appuie pour arrêter ton drain ou ton incantation et lancer le Trait de l’ombre instantané sur ta cible, ou sur ton mouseover avec Shift.",
        requires = "Talent Crépuscule. Sans Transe de l'ombre, la macro commence un Trait de l’ombre normal de 3 secondes. Si tu appuies dans les 1.5 premières secondes d'un drain ou d'une incantation, elle annule seulement celui-ci", mods = { "Annule ton incantation et lance Trait de l’ombre sur ta cible", "Annule ton incantation et lance Trait de l’ombre sur ton mouseover" } },
      ["pvp-pact-swap"] = { title = "Sacrifie en plein combat et fais vite venir un nouveau démon", use = "Sacrifie ton démon, puis Domination corrompue et un Marcheur du Vide du même appui, ou un modificateur pour un autre démon. Un Chasseur corrompu sacrifié rend 3 % de ta vie toutes les 4 secondes.",
