      ["pvp-pet-command"] = { title = "Attaque, rappel et passif du familier sur une touche", use = "Envoie ton démon sur ta cible, ou sur ton mouseover avec Shift, rappelle-le avec Ctrl ou mets-le en passif avec Alt.",
