      ["pvp-seduce-fear"] = { title = "Séduis ton mouseover et lance Peur sur ta cible", use = "Survole un deuxième ennemi et appuie : ta Succube le séduit pendant que tu commences Peur sur ta cible. Sans rien survoler, la macro lance simplement Peur.",
