      ["pvp-shadowburn-stop"] = { title = "Lâche ton incantation et Brûlure de l'ombre", use = "Annule ton Trait de l'ombre et achève ta cible en instantané avec Brûlure de l'ombre avant que le soin arrive, ou ton mouseover avec Shift.",
        requires = "Talent Brûlure de l'ombre et un Fragment d'âme ; temps de recharge de 15 secondes. Si tu appuies dans les 1.5 premières secondes d'une autre incantation, la macro annule seulement cette incantation", mods = { "Annule ton incantation et lance Brûlure de l'ombre sur ta cible", "Annule ton incantation et lance Brûlure de l'ombre sur ton mouseover" } },
      ["pvp-soul-fire-opener"] = { title = "Ouverture Feu de l'âme avec ton démon envoyé", use = "Ouvre sur un ennemi qui ne t'a pas vu : ton démon fonce dès que Feu de l'âme démarre. Pyroclasme donne au coup une chance d'étourdir.",
