      ["feral-primal-bite"] = { title = "Morsure primordiale et attaque auto", use = "Utilise le talent de Combat farouche renommé par Forever, sans couper l'attaque automatique.",
        requires = "Talent Morsure primordiale, qui nécessite désormais Chef de la meute ; Forme d’ours ou Forme d’ours redoutable", mods = {  } },
      ["feral-prowl"] = { title = "Descendre de monture, Forme de félin et Rôder", use = "Descends de monture et passe en Forme de félin si besoin, puis appuie à nouveau après le temps de recharge global pour lancer Rôder. Appuyer plusieurs fois une fois caché te laisse en Camouflage.",
        requires = "Forme de félin et Rôder appris", mods = {  } },
      ["feral-ravage-shred"] = { title = "Ravager depuis le camouflage, Lambeau sinon", use = "Ravage quand tu es en Rôder et Lambeau sinon ; l’attaque auto ne démarre qu’après l’ouverture. Les deux demandent d’être derrière la cible.",
        requires = "Forme de félin ; derrière ta cible", mods = {  } },
      ["feral-swipe-roar"] = { title = "Balayage, Shift pour Rugissement démoralisant", use = "Balayage avec l’attaque auto en cours, ou maintiens Shift pour Rugissement démoralisant.",
        requires = "Forme d’ours ou Forme d’ours redoutable", mods = { "Balayage", "Rugissement démoralisant" } },
      ["pvp-bash-stun"] = { title = "Sonner, en passant d’abord en Forme d’ours", use = "Lance Sonner sur ta cible, ou sur la cible survolée avec Shift ; si tu n’es pas en ours, la macro te met d’abord en Forme d’ours redoutable, et le second appui place l’étourdissement. Les Taurens peuvent ajouter Choc martial sur Ctrl.",
        requires = "Sonner appris ; Choc martial est réservé aux Taurens", mods = { "Sonner sur ta cible, ou d’abord Forme d’ours redoutable si tu n’y es pas", "Sonner sur la cible survolée", "Choc martial (Tauren)" } },
      ["pvp-break-snare"] = { title = "Changer de forme pour briser une immobilisation ou un ralentissement", use = "Changer de forme te libère des effets qui entravent le mouvement, donc cette macro change toujours de forme : félin vers ours, tout le reste vers félin, Forme de voyage en extérieur avec Shift, Forme aquatique avec Ctrl.",
        requires = "Forme de félin, Forme d’ours redoutable, Forme de voyage et Forme aquatique appris", mods = { "Forme de félin, ou Forme d’ours redoutable si tu es en Forme de félin", "Forme de voyage (en extérieur)", "Forme aquatique" } },
      ["pvp-cast-cancel"] = { title = "Interrompre l’incantation pour un instantané", use = "Interromps l’incantation en cours et lance Éclat lunaire sur ta cible ; Shift pour la cible survolée, Ctrl pour Essaim d'insectes, Alt pour Lucioles.",
        requires = "Talent Essaim d'insectes pour la partie Ctrl", mods = { "Éclat lunaire sur ta cible", "Éclat lunaire sur la cible survolée", "Essaim d'insectes sur ta cible", "Lucioles sur ta cible" } },
      ["pvp-cat-escape"] = { title = "Célérité et Écorce en Forme de félin", use = "Célérité et Écorce ensemble en Forme de félin, puisque Célérité ne déclenche pas le temps de recharge global. Hors Forme de félin, le premier appui te transforme, ce qui te libère aussi des immobilisations et des ralentissements.",
        requires = "Célérité et Écorce appris ; dans Forever, Écorce marche en Forme de félin", mods = {  } },
      ["pvp-cat-heal"] = { title = "Soin sur soi, puis retour en Forme de félin", use = "Quitte ta forme pour lancer Récupération puis Rétablissement sur toi ; le troisième appui te remet en Forme de félin. La séquence repart de zéro après 12 secondes sans appui.",
        requires = "Forme de félin et Rétablissement appris", mods = {  } },
      ["pvp-charge-bash"] = { title = "Enrager, charger et Sonner", use = "En Forme d’ours, elle lance Enrager pour la rage (ton armure baisse pendant 10 secondes), charge et lance Sonner ; appuie à nouveau si la rage manquait pour Sonner. Depuis toute autre forme, le premier appui ne fait que changer ta forme.",
        requires = "Talent Charge farouche ; Sonner appris", mods = { "Charge et Sonner sur ta cible", "Charge et Sonner sur la cible survolée" } },
      ["pvp-charge-grasp"] = { title = "Charge farouche avec Emprise de la nature", use = "En Forme d’ours, charge la cible survolée ou ta cible et active Emprise de la nature du même appui, pour que le prochain coup de mêlée que tu reçois immobilise son auteur. Hors Forme d’ours, le premier appui te transforme.",
        requires = "Talent Charge farouche ; Emprise de la nature, que Forever te laisse lancer en forme animale", mods = {  } },
      ["pvp-cleanse-self"] = { title = "Épuration sur toi ou un allié", use = "Délivrance de la malédiction sur la cible survolée ou sur toi, Abolir le poison avec Shift, et Ctrl ou Alt pour forcer l’un ou l’autre sur toi. Tu quittes d’abord ta forme.",
        requires = "Délivrance de la malédiction et Abolir le poison appris", mods = { "Délivrance de la malédiction sur la cible survolée ou sur toi", "Abolir le poison sur la cible survolée ou sur toi", "Délivrance de la malédiction sur toi", "Abolir le poison sur toi" } },
      ["pvp-instant-hibernate"] = { title = "Rapidité de la nature puis Hibernation", use = "Quitte ta forme et endors instantanément une bête ou un draconien, sur la cible survolée ou ta cible ennemie ; le familier d’un chasseur est le choix habituel. Si l’incantation ne peut pas démarrer, Rapidité de la nature reste en place.",
        requires = "Talent Rapidité de la nature ; Hibernation appris", mods = {  } },
      ["pvp-instant-party-heal"] = { title = "Toucher guérisseur instantané par place dans le groupe", use = "Interromps ton incantation, quitte ta forme et rends Toucher guérisseur instantané avec Rapidité de la nature, sur la cible survolée ou sur toi, ou sur le membre du groupe 1, 2 ou 3 avec Shift, Ctrl ou Alt.",
        requires = "Talent Rapidité de la nature", mods = { "Rapidité de la nature, puis Toucher guérisseur sur la cible survolée ou sur toi", "Rapidité de la nature, puis Toucher guérisseur sur le membre du groupe 1", "Rapidité de la nature, puis Toucher guérisseur sur le membre du groupe 2", "Rapidité de la nature, puis Toucher guérisseur sur le membre du groupe 3" } },
      ["pvp-instant-rebirth"] = { title = "Rapidité de la nature puis Renaissance", use = "Ramène le joueur mort sous ton curseur, ou ta cible, en lançant Renaissance en instantané en plein combat. Tu quittes d’abord ta forme, et Renaissance a 30 min de temps de recharge.",
        requires = "Talent Rapidité de la nature ; Renaissance appris", mods = {  } },
      ["pvp-leap-reveal"] = { title = "Bond du félin et Lucioles d’un seul appui", use = "Bondis derrière ta cible avec Charge farouche en félin et lance-lui Lucioles du même appui, pour qu’elle ne puisse ni se camoufler ni devenir invisible. Si l’un des sorts échoue, vérifie le nom sur ta barre d’action de félin.",
        requires = "Talent Charge farouche ; Forme de félin ; entre 8 et 25 mètres de ta cible", mods = {  } },
      ["pvp-moonkin-heal"] = { title = "Rétablissement, puis retour en Forme de sélénien", use = "Forme de sélénien bloque les soins, donc cette macro la quitte et lance Rétablissement sur toi ; l’appui suivant te remet dans la forme. La séquence repart de zéro après 10 secondes sans appui.",
        requires = "Talent Forme de sélénien", mods = {  } },
      ["pvp-moonkin-shift"] = { title = "Retour en Forme de sélénien pour briser une immobilisation", use = "Reprends Forme de sélénien pour te libérer d’une immobilisation, d’un ralentissement ou d’une Métamorphose ; depuis la Forme de sélénien, il peut falloir un second appui. Maintiens Shift pour Forme d’ours redoutable quand un voleur te saute dessus, ou Ctrl pour Forme de voyage en extérieur.",
        requires = "Talent Forme de sélénien ; Forme d’ours redoutable et Forme de voyage appris", mods = { "Forme de sélénien, en la quittant d’abord si tu y es déjà", "Forme d’ours redoutable", "Forme de voyage (en extérieur)" } },
      ["pvp-moonkin-support"] = { title = "Épuration ou Innervation sans quitter la Forme de sélénien", use = "Délivrance de la malédiction sur la cible survolée ou sur toi, Abolir le poison avec Shift, ou Innervation sur toi avec Ctrl. Dans Forever, la Forme de sélénien ne bloque que les sorts de soin, donc elle reste active ; les autres formes sautent.",
        requires = "Talent Forme de sélénien ; Délivrance de la malédiction, Abolir le poison et Innervation appris", mods = { "Délivrance de la malédiction sur la cible survolée ou sur toi", "Abolir le poison sur la cible survolée ou sur toi", "Innervation sur toi" } },
      ["pvp-moving-heals"] = { title = "Soins instantanés en mouvement", use = "Récupération sur un appui simple ou Prompte guérison avec Shift, tous deux instantanés, sur la cible survolée ou sur toi. Tu quittes d’abord ta forme.",
        requires = "Talent Prompte guérison ; Récupération ou Rétablissement lancé par toi sur la cible pour Prompte guérison", mods = { "Récupération sur la cible survolée ou sur toi", "Prompte guérison sur la cible survolée ou sur toi" } },
      ["pvp-panic-button"] = { title = "Bouton défensif selon le modificateur", use = "Écorce sur un appui simple, Emprise de la nature avec Ctrl, ou Enrager puis Régénération frénétique avec Shift en Forme d’ours. Écorce et Emprise de la nature marchent tous les deux en forme animale.",
        requires = "Écorce, Emprise de la nature et Régénération frénétique appris", mods = { "Écorce", "Enrager, puis Régénération frénétique (Forme d’ours)", "Emprise de la nature" } },
      ["pvp-peel-roots"] = { title = "Immobiliser l’ennemi de ton allié", use = "Immobilise l'ennemi sous ton curseur, ou survole le cadre d'un allié pour immobiliser sa cible ; sinon ta cible ennemie, ou la cible de ta cible amicale. Sans Lacis, une nouvelle immobilisation libère la précédente.",
        requires = "Sarments appris ; talent Lacis pour garder plus d’une cible immobilisée", mods = {  } },
      ["pvp-potion-in-form"] = { title = "Potion de libre action ou de rapidité sans quitter ta forme", use = "Bois une Potion de libre action, ou une Potion de rapidité en maintenant Shift, sans quitter ta forme. Forever permet aux druides d’utiliser des potions en forme animale ; dans Classic, il fallait d’abord quitter la forme.",
        requires = "Potion de libre action et Potion de rapidité dans tes sacs", mods = { "Potion de libre action", "Potion de rapidité" } },
      ["pvp-pounce-opener"] = { title = "Traquenard depuis le camouflage, Shift pour Ravager", use = "Étourdis avec Traquenard depuis Rôder, ou ouvre avec Ravage en maintenant Shift ; hors camouflage, la macro lance Griffure à la place. Les deux ouvertures demandent d’être derrière la cible.",
        requires = "Forme de félin ; derrière ta cible", mods = { "Traquenard depuis le camouflage, Griffure sinon", "Ravage depuis le camouflage" } },
      ["pvp-pounce-roots"] = { title = "Traquenard depuis Rôder, puis Sarments", use = "Traquenard depuis Rôder pour étourdir, puis appuie à nouveau pour quitter la Forme de félin et lancer Sarments pendant que la cible est encore étourdie. Traquenard demande d’être derrière la cible, et son saignement peut briser l’immobilisation.",
        requires = "Forme de félin et Rôder ; le talent d’amélioration de Sarments aide l’immobilisation à tenir malgré le saignement", mods = {  } },
      ["pvp-reveal"] = { title = "Lucioles sur ta cible ou en survol", use = "Lance Lucioles sur ta cible, ou sur la cible survolée avec Shift, pour empêcher le camouflage et l’invisibilité. Reste en forme d’ours, de félin, d’ours redoutable ou de sélénien ; en ours, félin et ours redoutable, le sort ne coûte aucune ressource et a 6 s de temps de recharge.",
        requires = "Lucioles appris. On n’a pas testé le nom de sort de Lucioles en forme animale. S’il échoue, utilise le nom affiché sur la barre d’action de ta forme.", mods = { "Lucioles sur ta cible", "Lucioles sur la cible survolée" } },
      ["pvp-roots-run"] = { title = "Sarments, Shift pour Forme de voyage, Ctrl pour Hibernation", use = "Immobilise la cible survolée ou ta cible, file en Forme de voyage avec Shift, ou endors une bête avec Ctrl (le familier d’un chasseur compte). Sarments marche en intérieur comme en extérieur.",
        requires = "Sarments, Hibernation et Forme de voyage appris", mods = { "Sarments sur la cible survolée ou ta cible", "Forme de voyage (en extérieur)", "Hibernation sur la cible survolée" } },
      ["pvp-starfire-burst"] = { title = "Bijou et Lumière d’Élune puis Feu stellaire", use = "Feu stellaire sur un appui simple. Maintiens Shift pour déclencher d’abord ton bijou du bas et Lumière d’Élune. On n’a pas vérifié si Lumière d’Élune déclenche le temps de recharge global ; si c’est le cas, appuie à nouveau pour lancer Feu stellaire.",
        requires = "Feu stellaire appris ; un bijou à utiliser dans ton emplacement du bas ; Lumière d’Élune est réservée aux Elfes de la nuit", mods = { "Feu stellaire", "Bijou du bas et Lumière d’Élune, puis Feu stellaire" } },
      ["pvp-stealth-dance"] = { title = "Rôder, Célérité ou Camouflage dans l’ombre sur une touche", use = "Passe en Forme de félin si besoin, puis Rôder, ou Célérité en maintenant Shift ; les Elfes de la nuit ont Camouflage dans l’ombre sur Ctrl.",
        requires = "Rôder et Célérité appris ; Camouflage dans l’ombre est réservé aux Elfes de la nuit", mods = { "Forme de félin si besoin, puis Rôder (hors combat)", "Forme de félin si besoin, puis Célérité", "Camouflage dans l’ombre (Elfe de la nuit)" } },
      ["pvp-swiftmend-party"] = { title = "Prompte guérison par place dans le groupe", use = "Lance Prompte guérison sur la cible survolée ou sur toi, ou sur le membre du groupe 1, 2 ou 3 avec Shift, Ctrl ou Alt. La cible doit avoir ta propre Récupération ou ton propre Rétablissement sur elle.",
        requires = "Talent Prompte guérison", mods = { "Prompte guérison sur la cible survolée ou sur toi", "Prompte guérison sur le membre du groupe 1", "Prompte guérison sur le membre du groupe 2", "Prompte guérison sur le membre du groupe 3" } },
      ["pvp-swiftness-pvp"] = { title = "Soin instantané ou immobilisation instantanée", use = "Rapidité de la nature suivi de Toucher guérisseur sur la cible survolée ou sur toi, ou d’un Sarments instantané sur ta cible en maintenant Shift.",
        requires = "Talent Rapidité de la nature", mods = { "Rapidité de la nature, puis Toucher guérisseur sur la cible survolée ou sur toi", "Rapidité de la nature, puis Sarments sur ta cible" } },
      ["pvp-totem-moonfire"] = { title = "Éclat lunaire rang 1 sur un totem de chaman", use = "Cible un Totem de glèbe et lance Éclat lunaire rang 1 dessus ; Shift pour Séisme, Ctrl pour Lien terrestre, Alt pour Vague de mana. Tu restes sur le totem, et s’il n’y en a aucun à portée, Éclat lunaire touche ta cible.",
        requires = "Éclat lunaire appris ; forme normale ou Forme de sélénien", mods = { "Éclat lunaire rang 1 sur un Totem de glèbe", "Éclat lunaire rang 1 sur un Totem de séisme", "Éclat lunaire rang 1 sur un Totem de lien terrestre", "Éclat lunaire rang 1 sur un Totem de vague de mana" } },
      ["pvp-travel-heal"] = { title = "Récupération, puis retour en Forme de voyage", use = "Pour porter le drapeau et kiter : quitte Forme de voyage et lance Récupération sur toi, puis appuie à nouveau pour reprendre la forme. Forme de voyage ne marche qu’en extérieur, et la séquence repart de zéro après 12 secondes sans appui.",
        requires = "Forme de voyage appris", mods = {  } },
      ["pvp-trinket-shift"] = { title = "Bijou PvP et Forme d’ours", use = "Interromps ton incantation, utilise ton bijou du haut en combat et passe en Forme d’ours redoutable, ou en Forme de félin avec Shift.",
        requires = "Un bijou PvP dans ton emplacement de bijou du haut, comme l’Insigne supérieur de l’Alliance ou de la Horde (rang Caporal ou Grunt, 5 min de temps de recharge)", mods = { "Bijou, puis Forme d’ours redoutable", "Bijou, puis Forme de félin" } },
      ["pvp-victim-heal"] = { title = "Soigner la cible de ta cible ennemie", use = "Garde un ennemi en cible et lance Récupération sur sa cible, ou Prompte guérison avec Shift. Une cible alliée reçoit le soin à la place, et à défaut, c’est toi. Tu quittes d’abord ta forme.",
        requires = "Talent Prompte guérison pour la partie Shift", mods = { "Récupération sur ta cible alliée, la cible de ta cible ennemie ou toi", "Prompte guérison sur ta cible alliée, la cible de ta cible ennemie ou toi" } },
      ["restoration-healing-touch-rank"] = { title = "Toucher guérisseur, Shift pour un rang inférieur", use = "Lance ton rang le plus élevé de Toucher guérisseur sur la cible survolée, ta cible ou toi, ou maintiens Shift pour le rang 3 quand un soin plus petit suffit ; change le chiffre selon ton niveau.",
        requires = "Toucher guérisseur rang 3 appris", mods = { "Toucher guérisseur à ton rang le plus élevé", "Toucher guérisseur rang 3" } },
      ["restoration-natures-swiftness"] = { title = "Rapidité de la nature puis un soin", use = "Quitte ta forme, active Rapidité de la nature et rends ton prochain soin instantané : Toucher guérisseur, ou Rétablissement en maintenant Shift.",
        requires = "Talent Rapidité de la nature", mods = { "Rapidité de la nature, puis Toucher guérisseur", "Rapidité de la nature, puis Rétablissement" } },
      ["restoration-regrowth"] = { title = "Rétablissement en survol ou sur la cible de ta cible", use = "Lance Rétablissement sur l’allié sous ton curseur, sur ta cible, sur celui que combat ta cible ennemie ou sur toi.",
        requires = "Rétablissement appris", mods = {  } },
      ["restoration-rejuv-party"] = { title = "Récupération par place dans le groupe", use = "Lance Récupération sur toi, ou maintiens Shift, Ctrl ou Alt pour les membres du groupe 1, 2 ou 3, sans toucher à un cadre.",
        requires = "Récupération appris", mods = { "Récupération sur toi", "Récupération sur le membre du groupe 1", "Récupération sur le membre du groupe 2", "Récupération sur le membre du groupe 3" } },
      ["restoration-rejuv-swiftmend"] = { title = "Récupération, puis Prompte guérison", use = "Récupération au premier appui et Prompte guérison au second, sur ta cible alliée ou sur toi, pour que le HoT dont Prompte guérison a besoin soit toujours le tien.",
        requires = "Talent Prompte guérison", mods = {  } },
      ["restoration-rejuvenation"] = { title = "Récupération en survol", use = "Soigne le cadre de groupe sous ton curseur, ta cible ou toi-même.",
        requires = "", mods = {  } },
      ["restoration-swiftmend"] = { title = "Prompte guérison en survol", use = "Lance Prompte guérison sur l’allié survolé, ta cible ou toi. Blizzard a dit le 30 septembre que le HoT continue ; l’infobulle la plus récente dit que Prompte guérison le consomme, donc on ne sait pas encore quelle version est en jeu.",
        requires = "Talent Prompte guérison ; ta propre Récupération ou ton propre Rétablissement déjà sur la cible", mods = {  } },
      ["restoration-tranquility-channel"] = { title = "Tranquillité, Shift pour l’arrêter", use = "Quitte ta forme et canalise Tranquillité. Les appuis répétés laissent la canalisation se poursuivre ; maintiens Shift pour l’arrêter plus tôt.",
        requires = "Tranquillité appris", mods = { "Lance Tranquillité sans relancer une canalisation en cours", "Arrête l'incantation" } },
      ["restoration-wild-growth"] = { title = "Croissance sauvage en survol", use = "Soigne le groupe et les familiers proches de l’allié survolé ou de ta cible en sept ticks dégressifs. C’est une incantation de 3 s, avec 6 s de temps de recharge. En raid, c’est la cible qui détermine quel groupe est soigné.",
        requires = "Talent Croissance sauvage", mods = {  } },
    },
  },
}
